/**
 * Hollow Keep — the Hollow Warden, the boss. A giant with a halberd; dormant until the fog gate wakes it,
 * never flinches, and at `phase2At` of its health it turns:
 *
 *   it ROARS (invulnerable for `phase2Seconds`), starts its `PhaseAura`, speeds up by `phase2SpeedMul`
 *   and unlocks every attack whose `phase` is 2 (the Leap and the Bolt Fan).
 *
 * The phase two lives here and nowhere else: a different boss writes its own `_onDamaged`.
 */
export default class SoulsHollowWardenNode extends SoulsEnemyNode {
  @attribute
  public displayName: string = 'Hollow Warden'
  @attribute
  public weaponTemplates: TemplateName[] = ['Halberd']
  @attribute
  public isBoss: boolean = true
  @attribute
  public flinchOnHit: boolean = false
  @attribute
  public maxHp: number = 2600
  @attribute
  public hp: number = 2600
  @attribute
  public defense: number = 0.2
  @attribute
  public maxPoise: number = 150
  @attribute
  public poise: number = 150
  @attribute
  public soulsReward: number = 6000
  @attribute
  public moveSpeed: number = 3
  @attribute
  public attackGapMin: number = 0.6
  @attribute
  public attackGapMax: number = 1.2
  @attribute
  public bodyRadius: number = 0.7
  @attribute
  public bodyHeight: number = 3.24
  @attribute
  public healthBarSeconds: number = 0
  @attribute
  public deathSeconds: number = 2.2
  @attribute
  public corpseSeconds: number = 20

  // ----- phase two -------------------------------------------------------------------------------
  /** Fraction of max HP at which the Warden turns. */
  @attribute('Phase two')
  public phase2At: number = 0.5
  @attribute('Phase two')
  public phase2SpeedMul: number = 1.15
  @attribute('Phase two')
  public phase2Seconds: number = 2
  /** The animator trigger of the roar's Actions state. */
  @attribute('Phase two')
  public roarTrigger: TriggerName = 'Roar'

  protected _onDamaged(dealt: number, poiseDamage: number, from: Node): void {
    super._onDamaged(dealt, poiseDamage, from)
    if (this.phase === 1 && this.hp <= this.maxHp * this.phase2At) this._startPhase2()
  }

  private _startPhase2(): void {
    this.phase = 2
    this._setSpeedMul(this.phase2SpeedMul)
    this._phaseSeconds = this.phase2Seconds
    this._enter('phase')
    this._oneShot(this.roarTrigger)
    const gm = this._gm as any
    gm?.shake?.(0.6)
    playSound(this, 'Boss Roar')
    ;(this._aura as any)?.play?.()
  }
}

import { Node } from 'cleo'
import { attribute } from 'cleo/decorators'
import type { NodeName, SoundName, TemplateName, TriggerName } from 'cleo'

/**
 * Hollow Keep — one attack of an enemy's moveset. Attach to a plain child of the enemy's `Attacks`
 * group; the node's NAME identifies it (for `comboNext` and for the no-repeat rule).
 *
 * ## Choosing
 *
 * When its attack gap runs out, an engaged enemy picks among the attacks that are off `cooldown`, whose
 * `minRange`..`maxRange` contains the distance to the player, and whose `phase` it has reached (0/1:
 * always; 2: boss phase two only). It avoids repeating the last one when anything else fits, then rolls
 * weighted by `weight`. See SoulsEnemy.pickAttack.
 *
 * ## Animation
 *
 * `animTrigger` names the animator trigger that plays the attack: the enemy type's animator has a state entered
 * by it, whose clip, speed and blends are the attack's animation. It plays at its speed times the animator's
 * `AttackSpeed` (raised in a boss's second phase).
 *
 * ## Timing
 *
 * A melee attack is ACTIVE from the clip's `hit` event to its `hitEnd` event (without them: from
 * `hitTime` for `activeSeconds`, clip seconds). While active, the enemy's weapon blade is swept every
 * frame against the player's hurtbox (SoulsHitbox), so it lands where the weapon actually is: a roll's
 * i-frames switch the hurtbox off, and stepping out of the arc works because the blade misses. With
 * `aoeRadius > 0` it is a slam that hits everything inside the radius at the `hit` event. With a
 * `projectileTemplate` the `cast` event fires `projectileCount` projectiles fanned over `spreadDeg`.
 *
 * ## Movement
 *
 * The enemy turns toward the player for `trackSeconds`, then commits. It lunges forward from
 * `lungeStart` (clip seconds) for `lungeSeconds` at `lungeSpeed`; `lungeToTarget` instead covers the
 * distance to the player (capped at `lungeSpeed`) — the boss's leap. Clips must be in place.
 */
export default class SoulsEnemyAttackNode extends Node {
  /** The animator trigger that plays this attack. Empty: the node's name. */
  @attribute
  public animTrigger: TriggerName = ''
  @attribute
  public damage: number = 70
  @attribute
  public poiseDamage: number = 20
  @attribute
  public minRange: number = 0
  @attribute
  public maxRange: number = 2.2
  @attribute
  public weight: number = 1
  @attribute
  public cooldown: number = 0
  @attribute
  public phase: number = 0
  @attribute
  public trackSeconds: number = 0.45
  @attribute
  public lungeStart: number = 0
  @attribute
  public lungeSeconds: number = 0
  @attribute
  public lungeSpeed: number = 0
  @attribute
  public lungeToTarget: boolean = false
  /** No flinch while this attack plays (poise breaks still stagger). */
  @attribute
  public hyperArmor: boolean = false
  /** Attack that follows immediately, without a gap, when the player is still in its range. */
  @attribute
  public comboNext: NodeName = ''
  /** Fallback active window (clip seconds) for a clip without `hit`/`hitEnd` events. */
  @attribute
  public hitTime: number = 0.6
  @attribute
  public activeSeconds: number = 0.15
  /** The swing bounces off walls (`blocksSwings` bodies). Off by default: AI swings beside walls a lot. */
  @attribute
  public bounceOff: boolean = false
  /** Ground-slam radius. 0 is an ordinary swing. */
  @attribute
  public aoeRadius: number = 0
  /** Effect template spawned at the enemy's feet on a slam. */
  @attribute
  public impactTemplate: TemplateName = ''
  /** Projectile template; non-empty makes this a ranged attack. */
  @attribute
  public projectileTemplate: TemplateName = ''
  @attribute
  public projectileSpeed: number = 12
  @attribute
  public projectileCount: number = 1
  @attribute
  public spreadDeg: number = 0
  /** Sound cue played when the attack starts (a SoundNode name under Sounds). */
  @attribute
  public sound: SoundName = 'Enemy Swing'
  @attribute
  public isEnemyAttack: boolean = true
}

import { ControllerNode, Node } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Hollow Keep — an enemy's brain script. Attach to the `Brain` child (the LAST child) of every enemy
 * template: a Controller node with Source: AI, Brain: Behaviour machine, linked to the type's AI graph
 * (`<Type> Brain.brain` under /AI).
 *
 * The GRAPH makes every decision — chase, close in, strafe, back off, attack, flinch, give up and walk
 * home — reading perception senses and the enemy's own fields. This script does the two things a graph
 * cannot express, in `onThink` (the last step of the control pass, so this frame's perception is in):
 *
 * 1. **Targeting.** The engine has no factions: perception offers every other Character, and auto-acquire
 *    would have enemies chase each other. So `autoAcquire` is off and the target is the nearest NOTICED
 *    character carrying `targetMarker` (the player sets `isPlayer`). A held target is kept until
 *    perception forgets it. `SoulsEnemy.receiveHit` also writes the attacker in directly, so an enemy hit
 *    from behind turns round.
 *
 * 2. **Home.** `goalPoint` is where the enemy spawned, which the graph's Return state paths back to.
 */
export default class SoulsEnemyBrainNode extends ControllerNode {
  @attribute
  public targetMarker: string = 'isPlayer'

  onThink(delta: number) {
    const pawn = this.possessed as any
    if (!pawn || pawn.isDead) return
    const key = this.targetKey

    const self = this.possessed.worldPosition
    // On patrol, "home" walks with the enemy: the leash is measured from where it LEFT its route, and
    // giving up a chase returns it there. Left at the spawn, a patrol that saw the player 25 m down the
    // road was already past its leash, so it gave up the chase the moment it began and never attacked.
    if (this.behaviorState === 'Patrol' && pawn.home) pawn.home = [self[0], self[1], self[2]]
    const home = pawn.home ?? [0, 0, 0]
    this.goalPoint = [home[0], home[1], home[2]]

    const held = this.getBlackboard(key)
    const heldId = typeof held === 'string' && held ? held : null
    let bestId: string = null
    let bestDistance = Infinity
    let heldRemembered = false
    for (const sighting of this.sightings) {
      const candidate = this.scene?.getNodeById(sighting.id)
      if (!candidate || !candidate.getVariable(this.targetMarker)) continue
      if (sighting.id === heldId && sighting.timeSinceSeen <= this.perception.memorySpan) heldRemembered = true
      if (!sighting.noticed) continue
      const p = candidate.worldPosition
      const d = Math.hypot(p[0] - self[0], p[1] - self[1], p[2] - self[2])
      if (d < bestDistance) { bestDistance = d; bestId = sighting.id }
    }
    // A held target written by `receiveHit` or `awaken` survives even unseen for the memory span; a boss
    // never forgets the player inside its arena.
    const heldValid = !!heldId && (heldRemembered || pawn.isBoss || this._heldFresh(heldId))
    this.setBlackboard(key, bestId ?? (heldValid ? heldId : undefined))
  }

  /**
   * A target written in from outside perception (a hit from behind) has no sighting yet. Keep it while
   * it is within perception range, so the enemy turns and closes in rather than shrugging it off.
   */
  private _heldFresh(id: string): boolean {
    const node = this.scene?.getNodeById(id)
    if (!node || !this.possessed) return false
    const a = node.worldPosition
    const b = this.possessed.worldPosition
    return Math.hypot(a[0] - b[0], a[2] - b[2]) <= this.perception.range
  }
}

import { Logger, Node } from 'cleo'
import { options, find, attribute } from 'cleo/decorators'
import type { TemplateName } from 'cleo'

/**
 * Hollow Keep — where an enemy lives. The script of the "Enemy Spawn" template: place a copy of it (and
 * rotate it) where the enemy should stand, and it instantiates `templateName` there.
 *
 * `spawnables` is the list of templates a spawn may make, edited once in the template; each placed copy
 * picks one of them for `templateName` from a dropdown in the inspector (its `@options` decorator).
 *
 * Enemies are TEMPLATES spawned at runtime rather than placed nodes, because resting at a bonfire must
 * bring every one of them back fresh — a placed node would need every field it ever changed restored by
 * hand. The spawn removes its previous instance (alive or corpse) and makes a new one.
 *
 * `isBossSpawn` marks the boss: it is created at the start and after a death mid-fight, but never by
 * resting, and never again once defeated. The manager is told about it so the HUD bar and the fog gate
 * can find the live boss.
 */
export default class SoulsEnemySpawnNode extends Node {
  /** The templates a spawn may create. Edit the list in the Enemy Spawn template. */
  @attribute
  public spawnables: TemplateName[] = ['Hollow', 'Hollow Sorcerer', 'Elite Knight', 'Hollow Warden']
  /** Which of `spawnables` this spawn creates. */
  @options('spawnables')
  @attribute
  public templateName: string = 'Hollow'
  @attribute
  public isBossSpawn: boolean = false
  /**
   * A patrol route on the scene's Nav Mesh, by name: the enemy walks it, looping, until it sees someone,
   * and goes back to it after giving up a chase. Empty: it stands where it spawned.
   */
  @attribute
  public patrolRoute: string = ''
  /** Seconds after the scene starts before the first spawn — lets the level settle first. */
  @attribute
  public initialDelay: number = 0.1

  @find('GameManager')
  private _gm: Node = null
  private _live: Node = null

  onStart() {
    ;(this._gm as any)?.registerSpawn?.(this)
    this.after(this.initialDelay, () => this.respawnEnemy())
  }

  /** Remove whatever this spawn made before, and make a fresh one. */
  public respawnEnemy(): void {
    if (this._live && this.scene?.getNodeById(this._live.id)) {
      // Its Collider, which the template placed and which carries the rest.
      try { (this._live.collider ?? this._live).remove() } catch { /* already gone */ }
    }
    this._live = null
    // A boss already defeated (in this game, or in the save it was loaded from) is never made again.
    if (this.isBossSpawn && (this._gm as any)?.bossDefeated) return
    if (!(this.spawnables ?? []).includes(this.templateName))
      Logger.warn('Hollow Keep: spawn "' + this.name + '" makes "' + this.templateName + '", which is not in its spawnables.', 'Script')
    const p = this.worldPosition
    const f = this.worldForward
    const yaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    // An enemy template's root is its Collider; the enemy is the Character in it.
    const root = this.scene?.instantiate(this.templateName, { position: [p[0], p[1], p[2]], rotation: [0, yaw, 0] })
    const enemy = root?.character ?? root
    if (!enemy) {
      Logger.warn('Hollow Keep: spawn "' + this.name + '" found no template "' + this.templateName + '".', 'Script')
      return
    }
    this._live = enemy
    if (this.patrolRoute) {
      // The brain is the enemy's AI controller: the one child with a route to walk.
      const brain: any = enemy.children.find((c: any) => 'routeName' in c)
      if (brain) brain.routeName = this.patrolRoute
      else Logger.warn('Hollow Keep: "' + this.templateName + '" has no AI controller to walk route "' + this.patrolRoute + '".', 'Script')
    }
    if (this.isBossSpawn) (this._gm as any)?.registerBoss?.(enemy)
  }

  /** The enemy this spawn made, or null. */
  public liveEnemy(): Node { return this._live }
}

import { Node } from 'cleo'
import { find, attribute } from 'cleo/decorators'
import type { TemplateName } from 'cleo'
import { playDetached } from '@/Core/Scripts/SoulsAudio'
import { hurtboxQuery, hurtboxTargets } from '@/Core/Scripts/SoulsHitbox'

/**
 * Hollow Keep — a magic bolt. Attach to the root of a projectile template (a plain node with the glowing
 * mesh, a light and a trail particle system beneath it). The firing enemy instantiates it at its hand and
 * calls `launch`.
 *
 * Flight is kinematic: every frame it moves `speed × delta` and sweeps that path twice, so a fast bolt
 * cannot tunnel through anything between two frames:
 *
 *   - a SPHERE of `radius` against the player's hurtbox (`physics.sweepSphere`). During a roll's i-frames
 *     the hurtbox is off (SoulsHitbox), so the sweep sees nothing and the bolt flies on through;
 *   - a ray against the world. Characters are skipped by the ray — the sphere handles them.
 *
 * On impact it spawns an effect and removes itself: `playerImpactTemplate` where it struck the player,
 * `impactTemplate` where it struck the world. It also expires after `lifetime` seconds, bursting where it
 * stopped.
 */
export default class SoulsProjectileNode extends Node {
  @attribute
  public speed: number = 12
  @attribute
  public damage: number = 90
  @attribute
  public poiseDamage: number = 30
  @attribute
  public lifetime: number = 4
  /** The bolt's hitbox: a sphere of this radius swept along its flight. */
  @attribute
  public radius: number = 0.2
  /** The effect where the bolt strikes the world, or runs out of flight. */
  @attribute
  public impactTemplate: TemplateName = 'Bolt Burst'
  /** The effect where it strikes the player. */
  @attribute
  public playerImpactTemplate: TemplateName = 'Bolt Impact'

  private _dir: number[] = [0, 0, 1]
  private _age: number = 0
  private _live: boolean = false
  private _owner: string = ''
  @find('GameManager')
  private _gm: Node = null

  onStart() {
  }

  /** Fire along `dir` (normalised here). Called by SoulsEnemy right after instantiating. */
  public launch(dir: number[], speed: number, damage: number, ownerId: string): void {
    const len = Math.hypot(dir[0], dir[1], dir[2]) || 1
    this._dir = [dir[0] / len, dir[1] / len, dir[2] / len]
    this.speed = speed
    this.damage = damage
    this._owner = ownerId
    this._age = 0
    this._live = true
    this.setRotation([0, Math.atan2(this._dir[0], this._dir[2]) * 180 / Math.PI, 0])
  }

  onUpdate(delta: number) {
    if (!this._live) return
    this._age += delta
    if (this._age >= this.lifetime) { this._expire('world'); return }

    const from = this.worldPosition
    const step = this.speed * delta
    const to = [from[0] + this._dir[0] * step, from[1] + this._dir[1] * step, from[2] + this._dir[2] * step]

    // The player's hurtbox trigger, by a swept sphere. Off during i-frames, so a roll passes straight through.
    const physics = this.scene?.physics as any
    const hits = hurtboxTargets(physics?.sweepSphere?.([from[0], from[1], from[2]], to, this.radius, hurtboxQuery('player', null)) ?? [])
      .filter(h => h.node.id !== this._owner)
    for (const h of hits) {
      if ((h.node as any).receiveHit(this.damage, this.poiseDamage, this, h.point)) {
        this.setPosition([h.point[0], h.point[1], h.point[2]])
        this._expire('player')
        return
      }
    }

    // The world, by raycast. Characters are skipped — the sweep above handles them.
    const hit = physics?.raycast?.([from[0], from[1], from[2]], to, {
      reject: (owner: Node) => !!owner && (owner.id === this._owner || owner.nodeType === 'character'
        || owner === this || owner.isDescendantOf?.(this)),
    })
    if (hit) {
      this.setPosition([hit.point[0], hit.point[1], hit.point[2]])
      this._expire('world')
      return
    }
    this.setPosition(to)
  }

  private _expire(on: 'player' | 'world'): void {
    this._live = false
    const gm = this._gm as any
    gm?.fx?.(on === 'player' ? this.playerImpactTemplate : this.impactTemplate, this.worldPosition)
    playDetached(this, 'Bolt Impact')
    // Immediate: the impact effect takes its place this frame.
    this.remove({ immediate: true })
  }
}

import { Node } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Hollow Keep — a fire-and-forget effect. Attach to the root of an effect template (hit spark, bolt
 * impact, slam dust). On start it bursts every Particle System child, fades every point light child over
 * `lifetime`, and removes itself when that time is up.
 *
 * Swap the look by editing the template's particle systems; this script only owns the lifetime.
 */
export default class SoulsFxNode extends Node {
  @attribute
  public lifetime: number = 1.2
  /** Particles per child system on start. 0 leaves them to their own spawn rate / bursts. */
  @attribute
  public burstCount: number = 0

  private _age: number = 0
  private _lights: any[] = []
  private _intensities: number[] = []

  onStart() {
    this._age = 0
    const walk = (node: Node) => {
      for (const child of node.children) {
        const c = child as any
        if (child.nodeType === 'particleSystem') {
          // play(), not restart(): a fresh instance is already playing if its system plays on start,
          // and a restart would clear and prewarm it a second time on its first frame.
          c.play?.()
          if (this.burstCount > 0) c.burst?.(this.burstCount)
        }
        if (child.nodeType === 'light' && c.light) {
          this._lights.push(c.light)
          this._intensities.push(c.light.intensity)
        }
        walk(child)
      }
    }
    walk(this)
  }

  onUpdate(delta: number) {
    this._age += delta
    const k = Math.max(0, 1 - this._age / Math.max(0.01, this.lifetime))
    for (let i = 0; i < this._lights.length; i++) this._lights[i].intensity = this._intensities[i] * k
    if (this._age >= this.lifetime) this.remove()
  }
}

import { Node } from 'cleo'
import { save, find, child, attribute } from 'cleo/decorators'

/**
 * Hollow Keep — a bonfire. Attach to the bonfire's root node.
 *
 *   Bonfire           this script
 *   ├── Model         the coiled sword and ash — swap freely
 *   ├── Fire          particle system, playing only while lit
 *   ├── Fire Light    point light, on only while lit
 *   └── RespawnPoint  empty node: where (and facing where) the player respawns
 *
 * `Fire` may instead be a whole fire carrying the Valley's Fire Light script (ValleyFireLight.ts), with its
 * flames, embers and light under it: then it is lit and put out through its `lit`, and `Fire Light` is optional.
 *
 * ## The interactable protocol
 *
 * Every interactable in Hollow Keep — this, pickups, bloodstains, messages, the lever, the door and the
 * fog gate — carries a TRIGGER volume (its interaction zone, authored on the node like a collider) and
 * implements the same three members. Walking into the zone makes it a candidate (the player's
 * onTriggerEnter); walking out removes it. Of the candidates whose `canInteract` passes, the player
 * prompts for the nearest and calls `interact` on Interact. No distance is measured in script:
 *
 *   canInteract(player): boolean    whether to offer it at all right now
 *   promptText(player): string      what the HUD prompt says
 *   interact(player): void          do it
 *
 * First use lights it (BONFIRE LIT, and it becomes the respawn point). After that, Interact rests:
 * heal, refill flasks, respawn enemies, open the level-up menu. Both save the game (the manager does).
 */
export default class SoulsBonfireNode extends Node {
  @attribute
  public startLit: boolean = false
  @attribute
  public lightIntensity: number = 900
  @attribute
  public isBonfire: boolean = true
  /** A bonfire lit before a save is still lit when it loads. */
  @save
  @attribute
  public lit: boolean = false

  @find('GameManager')
  private _gm: Node = null
  @child('Fire')
  private _fire?: Node
  @child('Fire Light')
  private _light?: Node

  onStart() {
    // A loaded game keeps the bonfire as it was (`lit` is @save); a new one starts as authored.
    if (!this.wasRestored) this.lit = this.startLit
    this._applyLit()
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean {
    return !(player as any)?.isDead
  }

  public promptText(player: Node): string {
    return this.lit ? 'Rest at bonfire' : 'Light bonfire'
  }

  public interact(player: Node): void {
    const p = player as any
    const gm = this._gm as any
    if (!this.lit) {
      this.lit = true
      this._applyLit()
      p.playGesture?.('Interact', 1)
      gm?.lightBonfire?.(this)
      return
    }
    p.sitAtBonfire?.()
    gm?.rest?.(this)
  }

  /** Where the player stands up after a death. */
  public respawnPoint(): Node {
    return this.getChildByName('RespawnPoint')[0] ?? this
  }

  private _applyLit(): void {
    const fire = this._fire as any
    if (fire && 'lit' in fire) fire.lit = this.lit
    else if (fire) { if (this.lit) fire.play?.(); else fire.stop?.(true) }
    const light = (this._light as any)?.light
    if (light) light.intensity = this.lit ? this.lightIntensity : 0
  }
}

import { Node } from 'cleo'
import { save, find, attribute } from 'cleo/decorators'
import type { TriggerName } from 'cleo'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — an item lying in the world (the glowing corpse loot of the souls games). Attach to the
 * item's root; its children are the visuals (a mesh, a glow particle system, a light) and are hidden
 * once it is taken.
 *
 *   kind = 'souls'        adds `amount` souls
 *   kind = 'flaskShard'   +1 maximum Estus, and fills it
 *   kind = 'flaskCharge'  refills `amount` Estus, up to the maximum
 *
 * Pickups are one-shot for the whole game — resting does not bring them back, and neither does loading a
 * save (`taken` is @save). `hiddenUntilRevealed` keeps one invisible and unreachable until something calls
 * `reveal()` (the boss's reward does this).
 *
 * See SoulsBonfire for the interactable protocol.
 */
export default class SoulsPickupNode extends Node {
  @attribute
  public kind: string = 'souls'
  @attribute
  public amount: number = 200
  @attribute
  public itemName: string = 'Soul of a Lost Undead'
  @attribute
  public hiddenUntilRevealed: boolean = false
  /** The trigger of the player animator's gesture state played on taking it. */
  @attribute
  public pickupGesture: TriggerName = 'Pickup'
  @save
  @attribute
  public taken: boolean = false

  @find('GameManager')
  private _gm: Node = null

  onStart() {
    // Taken before a save that was loaded: gone, and not offered again.
    if (this.taken) { this.visible = false; return }
    if (this.hiddenUntilRevealed) this.visible = false
    else (this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public reveal(): void {
    if (this.taken) return
    this.visible = true
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return !this.taken && this.visible }
  public promptText(player: Node): string { return 'Pick up ' + this.itemName }

  public interact(player: Node): void {
    if (this.taken) return
    const p = player as any
    const gm = this._gm as any
    this.taken = true
    p.playGesture?.(this.pickupGesture, 0.8)
    if (this.kind === 'souls') p.addSouls?.(this.amount)
    // The flasks are the player's; it is asked to change them, never written to.
    else if (this.kind === 'flaskShard') p.addEstusFlask?.()
    else if (this.kind === 'flaskCharge') p.refillEstus?.(this.amount)
    gm?.notice?.('Picked up ' + this.itemName)
    playSound(this, 'Pickup')
    this.visible = false
    gm?.unregisterInteractable?.(this)
  }
}

import { Node } from 'cleo'
import { save, find, attribute } from 'cleo/decorators'

/**
 * Hollow Keep — the bloodstain left where the player died, holding every soul they carried. Attach to
 * the root of the `Bloodstain` template; the GameManager instantiates it on every death and sets `souls`.
 *
 * Touch it to get the souls back. Die again before you do and the manager replaces it with a new one —
 * the old souls are gone for good. See SoulsBonfire for the interactable protocol.
 *
 * It is also the pool of blood where the player last died: its decal children play their flipbook (a pool
 * spreading) when it appears. With no souls in it, it is only that: its `Glow` hides and there is nothing
 * to retrieve.
 *
 * The template's root is Saved: a save made after a death keeps the stain where it lies, with its souls.
 */
export default class SoulsBloodstainNode extends Node {
  @save
  @attribute
  public souls: number = 0

  @find('GameManager')
  private _gm: Node = null
  private _taken: boolean = false
  private _shown: boolean = false

  onStart() {
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onUpdate() {
    // On the first frame, once the manager has set `souls` (it does so right after instantiating).
    if (this._shown) return
    this._shown = true
    for (const c of this.children) {
      if (c.nodeType === 'decal') (c as any).playFlipbook?.()
      else if (c.name === 'Glow' && !(this.souls > 0)) c.visible = false
    }
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return !this._taken && this.souls > 0 && !(player as any)?.isDead }
  public promptText(player: Node): string { return 'Retrieve souls' }

  public interact(player: Node): void {
    if (this._taken) return
    this._taken = true
    const p = player as any
    p.playGesture?.('Pickup', 0.8)
    p.addSouls?.(this.souls)
    const gm = this._gm as any
    gm?.onBloodstainRecovered?.(this)
    gm?.notice?.('Souls retrieved')
    this.remove()
  }
}

import { Node } from 'cleo'
import { attribute } from 'cleo/decorators'
import { clamp, num } from '@/Core/Scripts/SoulsMath'

/**
 * Hollow Keep — a blood decal on the ground. Attach to the root of a template whose children include
 * Decal nodes (`Blood Splat`, `Blood Drops`); the GameManager instantiates one where a hit lands and
 * sets `yaw` and `sizeScale` on it (see `bleed`).
 *
 * On its first frame it finds the floor below with a raycast, moves there and tilts so its decals
 * project straight into the surface — a ramp included — then gives them a random size. It removes
 * itself when there is no floor in reach: blood is never left hanging over a drop. After `lifetime`
 * it fades out over `fadeSeconds` and is removed.
 *
 * Placement waits for the first update rather than onStart, so the spawner's `yaw` and `sizeScale` are
 * in place whichever runs first; the decals stay invisible until then. A decal with a flipbook (the FX
 * Creator's liquid decals: the blood landing and spreading) plays it from that moment, `flipbookStart`
 * seconds in.
 */
export default class SoulsBloodSplatNode extends Node {
  /** Seconds before the splat is gone, its fade included. */
  @attribute
  public lifetime: number = 12
  /** The last part of `lifetime`, over which the decals fade out. */
  @attribute
  public fadeSeconds: number = 3
  /** Random size range, as a multiple of each decal's authored size. */
  @attribute
  public minSize: number = 0.65
  @attribute
  public maxSize: number = 1.25
  /** How far below the spawn point the floor may be. */
  @attribute
  public snapDown: number = 2.5
  /** Tilt onto sloped ground. Off, the splat lies flat and the decal's angle fade handles the slope. */
  @attribute
  public alignToSurface: boolean = true
  /** Set by the spawner. Which way the decal's +Z points, in degrees; NaN for a random turn. */
  @attribute
  public yaw: number = NaN
  /** Set by the spawner: a bigger hit leaves a bigger splat. */
  @attribute
  public sizeScale: number = 1
  /**
   * Seconds into a decal's flipbook it starts from: skip the frames before the liquid reaches the floor
   * when nothing else (a spray of droplets) covers that gap. 0 plays it from its first frame.
   */
  @attribute
  public flipbookStart: number = 0

  private _age: number = 0
  private _placed: boolean = false
  private _decals: any[] = []
  private _sizes: number[][] = []
  /** Each decal's authored place under the root (a liquid bake's decal stands where its liquid lay). */
  private _offsets: number[][] = []

  onStart() {
    this._decals = this.children.filter(c => c.nodeType === 'decal')
    this._sizes = this._decals.map(d => [...d.size])
    this._offsets = this._decals.map(d => [d.position[0], d.position[1], d.position[2]])
    for (const d of this._decals) d.opacity = 0
  }

  onUpdate(delta: number) {
    if (!this._placed) {
      this._placed = true
      if (!this._place()) { this.remove({ immediate: true }); return }
    }
    this._age += delta
    const fade = Math.max(0.01, this.fadeSeconds)
    const k = clamp((this.lifetime - this._age) / fade, 0, 1)
    for (const d of this._decals) d.opacity = k
    // Its own opacity fade has already run; nothing is left to dissolve.
    if (this._age >= this.lifetime) this.remove({ immediate: true })
  }

  /** Snap onto the floor below, turn, size. False when there is no floor in reach. */
  private _place(): boolean {
    // Spawned this frame, its world matrix may not have been computed yet: do it now, from the parent's.
    this.updateTransforms(this.parent ? this.parent.worldTransform : null)
    const p = this.worldPosition
    const physics = this.scene?.physics as any
    const hit = physics?.raycast?.([p[0], p[1] + 0.5, p[2]], [p[0], p[1] - this.snapDown, p[2]], {
      reject: (owner: Node) => isCharacterPart(owner),
    })
    if (!hit) return false

    const yaw = Number.isFinite(this.yaw) ? this.yaw : Math.random() * 360
    const n = hit.normal
    // Local +Y onto the surface normal: rotations compose Ry(yaw)·Rx(pitch), and Rx(p)·(0,1,0) turned by
    // Ry(y) is (sin p sin y, cos p, sin p cos y). That spends the root's yaw on the slope's own heading, so
    // on a slope the decals turn the rest of the way about the normal themselves: the spatter still runs
    // along the blow.
    const tilt = this.alignToSurface ? Math.acos(clamp(n[1], -1, 1)) * 180 / Math.PI : 0
    const heading = Math.atan2(n[0], n[2]) * 180 / Math.PI
    const sloped = tilt > 2
    this.setPosition([hit.point[0], hit.point[1], hit.point[2]])
    this.setRotation(sloped ? [tilt, heading, 0] : [0, yaw, 0])
    const turn = sloped ? yaw - heading : 0
    for (const d of this._decals) d.setRotation([0, turn, 0])

    const scale = num(this.sizeScale, 1) * (this.minSize + Math.random() * Math.max(0, this.maxSize - this.minSize))
    const c = Math.cos(turn * Math.PI / 180), sn = Math.sin(turn * Math.PI / 180)
    this._decals.forEach((d, i) => {
      const s = this._sizes[i]
      // Height stays: it is how far the projection reaches, not how big the splat looks.
      d.size = [s[0] * scale, s[1], s[2] * scale]
      // Its place scales with it, and turns with it on a slope (Ry(turn), as its own rotation).
      const o = this._offsets[i]
      d.setPosition([(o[0] * c + o[2] * sn) * scale, o[1], (-o[0] * sn + o[2] * c) * scale])
      d.opacity = 1
      if (d.flipbook) d.flipbookTime = Math.max(0, num(this.flipbookStart, 0))
    })
    return true
  }
}

/** A character, or anything inside one (a ragdolled limb): blood lands on the floor, not on a body. */
function isCharacterPart(owner: Node): boolean {
  // A character's body is its Collider, which holds the character.
  if (owner?.character) return true
  for (let n: Node = owner; n; n = n.parent) if (n.nodeType === 'character') return true
  return false
}

import { Node } from 'cleo'
import { find, attribute } from 'cleo/decorators'

/**
 * Hollow Keep — a readable message on the ground: tutorial hints and lore. Attach to the message's root
 * (a glowing glyph mesh and a few motes). Interact shows `title` and `text` in the HUD's message panel,
 * which closes when the player presses Interact again or walks away.
 *
 * `\n` in `text` is a line break. See SoulsBonfire for the interactable protocol.
 */
export default class SoulsMessageNode extends Node {
  @attribute
  public title: string = 'A message'
  @attribute
  public text: string = 'Try rolling.'
  @attribute
  public hiddenUntilRevealed: boolean = false

  @find('GameManager')
  private _gm: Node = null

  onStart() {
    if (this.hiddenUntilRevealed) this.visible = false
    else (this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public reveal(): void {
    this.visible = true
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return this.visible }
  public promptText(player: Node): string { return 'Read message' }

  public interact(player: Node): void {
    const gm = this._gm as any
    gm?.showMessage?.(this.title, this.text.split('\\n').join('\n'), this)
  }
}

import { Node } from 'cleo'
import { save, find, child, attribute } from 'cleo/decorators'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — a lever that opens a door elsewhere (the shortcut back to the bonfire). Attach to the
 * lever's root; a child named `Handle` is swung through `swingDegrees` about X when pulled.
 *
 * One use. `doorName` names a node carrying SoulsDoor. See SoulsBonfire for the interactable protocol.
 * A save keeps `pulled` (the door keeps its own `isOpen`), so a loaded game finds the lever down.
 */
export default class SoulsLeverNode extends Node {
  @attribute
  public doorName: string = 'Shortcut Gate'
  @attribute
  public swingDegrees: number = 70
  @attribute
  public swingSeconds: number = 0.6
  @save
  @attribute
  public pulled: boolean = false

  @find('GameManager')
  private _gm: Node = null
  @child('Handle')
  private _handle?: Node
  private _t: number = -1
  private _rest: number[] = [0, 0, 0]

  onStart() {
    if (this._handle) { const r = this._handle.rotation; this._rest = [r[0], r[1], r[2]] }
    // Pulled before a save that was loaded: the handle down, and nothing left to offer.
    if (this.pulled) {
      this._handle?.setRotation([this._rest[0] + this.swingDegrees, this._rest[1], this._rest[2]])
      return
    }
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean { return !this.pulled }
  public promptText(player: Node): string { return 'Pull lever' }

  public interact(player: Node): void {
    if (this.pulled) return
    this.pulled = true
    this._t = 0
    ;(player as any).playGesture?.('Interact', 0.9)
    const gm = this._gm as any
    playSound(this, 'Lever')
    const door = this.findNode(this.doorName) as any
    if (door?.openDoor) this.after(this.swingSeconds, () => door.openDoor())
    gm?.unregisterInteractable?.(this)
  }

  onUpdate(delta: number) {
    if (this._t < 0 || !this._handle) return
    this._t = Math.min(1, this._t + delta / Math.max(0.01, this.swingSeconds))
    const k = this._t * this._t * (3 - 2 * this._t)
    this._handle.setRotation([this._rest[0] + this.swingDegrees * k, this._rest[1], this._rest[2]])
    if (this._t >= 1) this._t = -1
  }
}

import { Node } from 'cleo'
import { save, find, attribute } from 'cleo/decorators'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — a door or portcullis that slides open. Attach to a node with a STATIC box body at the
 * scene root (or under an untransformed group); its visual is the node's own model or a child.
 *
 * Opened by a lever (`openDoor()`). From the locked side it is an interactable that only says why it
 * will not open — the souls convention that tells the player a shortcut exists. "Locked side" is the
 * side the node's local +Z points AWAY from when `lockedFromFront` is false, and toward when true.
 *
 * The slide moves the whole node, body included, so nothing else needs to know the door moved. A save keeps
 * `isOpen`, and the door opens itself as the scene starts; the door must NOT be marked Saved as well, or its
 * saved position would be opened a second time.
 */
export default class SoulsDoorNode extends Node {
  /** Offset from the closed position when fully open, in world metres. */
  @attribute
  public openOffset: [number, number, number] = [0, 4.2, 0]
  @attribute
  public openSeconds: number = 1.6
  @save
  @attribute
  public isOpen: boolean = false
  @attribute
  public lockedText: string = 'Opens from the other side'
  @attribute
  public lockedFromFront: boolean = false

  @find('GameManager')
  private _gm: Node = null
  private _closed: number[] = [0, 0, 0]
  private _t: number = 0
  private _opening: boolean = false

  onStart() {
    const p = this.position
    this._closed = [p[0], p[1], p[2]]
    if (this.isOpen) this._apply(1)
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean {
    if (this.isOpen || this._opening || !player) return false
    const p = player.worldPosition
    const me = this.worldPosition
    const f = this.worldForward
    const front = (p[0] - me[0]) * f[0] + (p[2] - me[2]) * f[2] > 0
    return front === this.lockedFromFront
  }

  public promptText(player: Node): string { return 'Examine' }

  public interact(player: Node): void {
    ;(this._gm as any)?.notice?.(this.lockedText)
  }

  public openDoor(): void {
    if (this.isOpen || this._opening) return
    this._opening = true
    this._t = 0
    playSound(this, 'Door')
  }

  onUpdate(delta: number) {
    if (!this._opening) return
    this._t = Math.min(1, this._t + delta / Math.max(0.01, this.openSeconds))
    this._apply(this._t * this._t * (3 - 2 * this._t))
    if (this._t >= 1) {
      this._opening = false
      this.isOpen = true
      ;(this._gm as any)?.notice?.('A shortcut has opened')
    }
  }

  private _apply(k: number): void {
    this.setPosition([
      this._closed[0] + this.openOffset[0] * k,
      this._closed[1] + this.openOffset[1] * k,
      this._closed[2] + this.openOffset[2] * k,
    ])
  }
}

import { Node } from 'cleo'
import { save, find, child, attribute } from 'cleo/decorators'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the fog wall in front of the boss. Attach to a node at the arena's mouth that carries a
 * STATIC box body (the blocker), with its local +Z pointing INTO the arena.
 *
 *   Fog Gate          this script + box body
 *   ├── FogWall       the translucent sheet — any mesh
 *   └── Fog           particle system, the drifting fog
 *
 *   closed    blocks both ways. From OUTSIDE, Interact: "Traverse the white fog". The player is lined
 *             up, walks through over `walkSeconds` with i-frames while the body is a ghost, and the
 *             fight starts on the far side.
 *   fight     blocks both ways, no prompt — there is no leaving.
 *   gone      the boss is dead: the fog dissolves for good.
 *
 * A death mid-fight resets it to `closed` (the manager calls `resetGate`). A save keeps `gateState`, so a
 * game loaded after the boss fell finds the way open.
 *
 * The prompt comes from the gate's TRIGGER volume (a box spanning both sides of the wall): standing in it
 * offers "Traverse", and `canInteract` only allows it from outside. A separate `Boss Arena` zone (a
 * trigger with the `isBossArena` variable) starts the fight if the player ever gets inside without
 * walking through.
 */
export default class SoulsFogGateNode extends Node {
  /** Metres in front of the gate (outside) the player is lined up at before walking. */
  @attribute
  public entryDistance: number = 1.1
  @attribute
  public walkDistance: number = 2.8
  @attribute
  public walkSeconds: number = 1.5
  @attribute
  public isFogGate: boolean = true
  /** 'closed' | 'fight' | 'gone' */
  @save
  @attribute
  public gateState: string = 'closed'

  @find('GameManager')
  private _gm: Node = null
  @child('Fog')
  private _fog?: Node
  @child('FogWall')
  private _wall?: Node
  private _fade: number = -1

  onStart() {
    // A loaded game: the fog the boss's death dissolved stays gone; a fight is never resumed mid-way.
    if (this.gateState === 'fight') this.gateState = 'closed'
    if (this.gateState === 'gone') {
      this._solid(false)
      ;(this._fog as any)?.stop?.()
      if (this._wall) this._wall.visible = false
    } else this._solid(true)
    ;(this._gm as any)?.registerInteractable?.(this)
  }

  onDespawn() {
    ;(this._gm as any)?.unregisterInteractable?.(this)
  }

  public canInteract(player: Node): boolean {
    if (this.gateState !== 'closed' || !player) return false
    return this._side(player.worldPosition) < 0
  }

  public promptText(player: Node): string { return 'Traverse the white fog' }

  public interact(player: Node): void {
    const p = player as any
    if (!p.walkThroughFog) return
    const me = this.worldPosition
    const f = this._forward()
    const start = [me[0] - f[0] * this.entryDistance, player.worldPosition[1], me[2] - f[2] * this.entryDistance]
    const yaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    this._solid(false)
    p.walkThroughFog(start, yaw, this.walkDistance, this.walkSeconds)
    playSound(this, 'Fog')
    this.after(this.walkSeconds + 0.05, () => {
      this._solid(true)
      this.gateState = 'fight'
      ;(this._gm as any)?.startBossFight?.(this)
    })
  }

  /** The boss died: fade the fog out and leave the way open. */
  public dissolve(): void {
    this.gateState = 'gone'
    this._solid(false)
    ;(this._fog as any)?.stop?.()
    this._fade = 0
  }

  /** The player died mid-fight. */
  public resetGate(): void {
    if (this.gateState === 'gone') return
    this.gateState = 'closed'
    this._solid(true)
  }

  onUpdate(delta: number) {
    if (this._fade < 0) return
    this._fade += delta
    const wall = this._wall as any
    if (wall && this._fade > 1.2 && wall.visible) wall.visible = false
    if (this._fade > 1.2) this._fade = -1
  }

  /** Signed distance of a point along the gate's forward: negative outside, positive inside. */
  private _side(point: ArrayLike<number>): number {
    const me = this.worldPosition
    const f = this._forward()
    return (point[0] - me[0]) * f[0] + (point[2] - me[2]) * f[2]
  }

  private _forward(): number[] {
    const f = this.worldForward
    const len = Math.hypot(f[0], f[2]) || 1
    return [f[0] / len, 0, f[2] / len]
  }

  private _solid(on: boolean): void {
    const body = this.body as any
    if (body) body.simulatePhysics = on
  }
}

import { Node } from 'cleo'
import { attribute } from 'cleo/decorators'
import type { TemplateName } from 'cleo'
import { playDetached } from '@/Core/Scripts/SoulsAudio'

/**
 * A prop that shatters: struck by the player's swing, or rolled into, it swaps itself for a pile of
 * physics debris (a separate template, `debrisTemplate`) and dissolves away. Attach to the root of
 *
 *   Breakable Barrel     this script + a STATIC body (it blocks like any prop) + a trigger a little
 *   ├── Mesh             wider than the body (how a roll is noticed before the body stops it)
 *   ├── Hurtbox          a trigger the size of the body, in the enemy hurtbox layer: what a blade hits
 *   └── Sounds           Break
 *
 * It is a target for the player's swings -- `team = 'enemy'`, `receiveHit` and its Hurtbox are what
 * SoulsHitbox looks for -- without being an enemy: nothing registers it with the manager, so lock-on, the
 * HUD and the enemy count never see it. Not `blocksSwings`: a blade that bounced off it could never break it.
 */
export default class SoulsBreakableNode extends Node {
  /** The template spawned in its place, one physics body per piece. See SoulsDebris. */
  @attribute
  public debrisTemplate: TemplateName = 'Barrel Debris'
  /** Metres per second the pieces leave at, along the blow. */
  @attribute
  public breakSpeed: number = 3.5
  /** A roll breaks it only this fast or faster (metres per second). */
  @attribute
  public rollBreakSpeed: number = 2
  @attribute
  public breakSound: string = 'Break'
  @attribute
  public team: string = 'enemy'
  @attribute
  public isBreakable: boolean = true
  @attribute
  public isBroken: boolean = false
  @attribute
  public hurtboxActive: boolean = true

  private _inside: Node[] = []

  /** SoulsHitbox's damage hook: any hit breaks it, pushed away from whoever struck. */
  public receiveHit(_damage: number, _poise: number, from: Node, _point?: ArrayLike<number>): boolean {
    if (this.isBroken) return false
    const me = this.worldPosition
    const at = from ? from.worldPosition : me
    this.shatter([me[0] - at[0], 0.6, me[2] - at[2]])
    return true
  }

  onStart() {
    // The roll zone is a Trigger of its own under the barrel (the Hurtbox is SoulsHitbox's): hear it here.
    for (const zone of this.children) {
      if (zone.nodeType !== 'trigger' || zone.name === 'Hurtbox') continue
      zone.onTriggerEnter = (other: Node) => this.onTriggerEnter(other)
      zone.onTriggerExit = (other: Node) => this.onTriggerExit(other)
    }
  }

  onTriggerEnter(other: Node) {
    // What came in is a body: a character's is its Collider, and the character is what rolls.
    const who = other?.character ?? other
    if (who && !this._inside.includes(who)) this._inside.push(who)
  }

  onTriggerExit(other: Node) {
    const who = other?.character ?? other
    this._inside = this._inside.filter(n => n !== who)
  }

  onUpdate() {
    if (this.isBroken) return
    // Rolled into: the player is inside the zone mid-roll and actually moving.
    for (const n of this._inside) {
      const p = n as any
      if (p.actionState !== 'roll') continue
      const v = p.velocity as ArrayLike<number> | undefined
      if (v && Math.hypot(v[0], v[2]) < this.rollBreakSpeed) continue
      this.shatter(v ? [v[0], 0.4, v[2]] : [0, 0.4, 0])
      return
    }
  }

  /**
   * Break now, the pieces leaving along `push` (any length; its direction is used). Spawns the debris
   * where this stands, then removes itself -- which dissolves whatever is left of it (see Node.remove).
   */
  public shatter(push: ArrayLike<number> = [0, 0.5, 0]): void {
    if (this.isBroken) return
    this.isBroken = true
    this.hurtboxActive = false
    const len = Math.hypot(push[0], push[1], push[2]) || 1
    const velocity = [push[0] / len * this.breakSpeed, push[1] / len * this.breakSpeed, push[2] / len * this.breakSpeed]

    const scene = this.scene as any
    const at = Array.from(this.worldPosition)
    const rot = Array.from(this.rotation as ArrayLike<number>)
    let debris: any = null
    try { debris = scene?.instantiate?.(this.debrisTemplate, { position: at, rotation: rot }) } catch { debris = null }
    debris?.burst?.(velocity)

    playDetached(this, this.breakSound)
    // Its own body and mesh go at once -- the debris stands exactly where they were.
    this.remove({ immediate: true })
  }
}

import { Node, Shape } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * The pieces of something that broke (see SoulsBreakable). Attach to the root of a template whose
 * children are the pieces, posed where they sat in the whole object:
 *
 *   Barrel Debris      this script
 *   ├── Stave 1        a model each, positioned in the intact shape
 *   ├── Lid Plank 2
 *   └── ...
 *
 * `burst(velocity)` gives every piece a dynamic box body fitted to its mesh -- moved to the scene root
 * first, since a body must not be parented -- an outward kick from the centre plus `velocity`, and a
 * spin. Each piece then lies for `lifeSeconds` (staggered a little) and dissolves away (Node.remove).
 * A copy placed by hand bursts on its own the frame after it starts.
 */
export default class SoulsDebrisNode extends Node {
  /** Seconds a piece lies there before it dissolves. */
  @attribute
  public lifeSeconds: number = 6
  /** Spread of that, so the pile does not vanish in one frame. */
  @attribute
  public lifeJitter: number = 1.5
  /** Metres per second each piece flies out from the centre, on top of the burst velocity. */
  @attribute
  public scatterSpeed: number = 2
  /** Radians per second of tumble, at most. */
  @attribute
  public spin: number = 8
  /** Kilograms per cubic metre of a piece's box: wood is around 600. */
  @attribute
  public density: number = 600

  private _burst: boolean = false
  private _pieces: Node[] = []

  onStart() {
    this.after(0, () => { if (!this._burst) this.burst([0, 0, 0]) })
  }

  public burst(velocity: ArrayLike<number>): void {
    if (this._burst) return
    this._burst = true
    const root = this.scene?.root
    if (!root) return
    this.updateTransforms?.()
    const centre = Array.from(this.worldPosition)
    let longest = 0
    for (const piece of [...this.children]) {
      const model = (piece as any).model
      if (!model?.geometry) continue
      const bb = model.geometry.boundingBox
      const s = piece.worldScale
      const size = [0, 1, 2].map(a => Math.max(0.02, (bb.max[a] - bb.min[a]) * Math.abs(s[a])))
      const offset = [0, 1, 2].map(a => (bb.min[a] + bb.max[a]) / 2 * s[a])

      const at = Array.from(piece.worldPosition), q = Array.from(piece.worldQuaternion)
      root.addChild(piece)
      piece.setPosition([at[0], at[1], at[2]])
      piece.setQuaternion(q as any)
      piece.updateTransforms?.()

      const mass = Math.max(0.2, size[0] * size[1] * size[2] * this.density)
      // The box takes the node's scale itself (Shape.Box scales by it), so it is given in local units.
      const body: any = piece.setBody(mass, 0.1, 0.3, undefined, undefined, 0.8, 0.05, true, false)
      body.attachShape(Shape.Box(size[0] / Math.abs(s[0] || 1), size[1] / Math.abs(s[1] || 1), size[2] / Math.abs(s[2] || 1), s as any),
        offset as any)
      body.recenterMass?.()

      // Out from the centre, up a little, plus the blow.
      const out = [at[0] - centre[0], 0, at[2] - centre[2]]
      const len = Math.hypot(out[0], out[2]) || 1
      const kick = this.scatterSpeed * (0.6 + Math.random() * 0.6)
      ;(piece as any).velocity = [
        velocity[0] + out[0] / len * kick,
        velocity[1] + 1 + Math.random() * 1.5,
        velocity[2] + out[2] / len * kick,
      ]
      body.angularVelocity?.set?.((Math.random() * 2 - 1) * this.spin, (Math.random() * 2 - 1) * this.spin, (Math.random() * 2 - 1) * this.spin)

      const life = this.lifeSeconds + Math.random() * this.lifeJitter
      longest = Math.max(longest, life)
      piece.after(life, () => piece.remove())
      this._pieces.push(piece)
    }
    // The empty root outlives the pieces' dissolve, then goes too.
    this.after(longest + (this.scene as any)?.despawnFadeSeconds + 0.5, () => this.remove({ immediate: true }))
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Hollow Keep — the PLAYER's HUD. Attach to the `HUD` node, a screen-space UI Root that is a CHILD of
 * the player (in the Player template): the HUD belongs to the character it shows, and reads that
 * character — its parent — not some node found by name. A second player would bring its own HUD.
 *
 * One script for the whole HUD. It finds its widgets by NAME once (missing ones are skipped, so you can
 * restyle or rebuild the HUD freely as long as the names stay) and writes them every frame from its
 * owner's public fields:
 *
 *   Health, HealthLag        uiProgressBar   HP, and the yellow "damage taken" bar that drains behind it
 *   Stamina                  uiProgressBar
 *   Estus                    uiText          flask count
 *   Weapon                   uiText          weapon in hand
 *   Souls, SoulsGain         uiText          souls held, and the +N popup
 *   Prompt / PromptText      uiPanel/uiText  "E  Rest at bonfire" — hidden when there is nothing to do
 *   Notice                   uiText          one-line messages ("Picked up ..."), fading
 *   Message / MessageTitle / MessageBody     the readable-message panel
 *
 * The boss bar is not here: it belongs to the boss (SoulsBossBar, inside the Hollow Warden template).
 *
 * Bars grow with their maximum (`pxPerHp`, `pxPerStamina`), so levelling Vigor visibly lengthens the bar.
 */
export default class SoulsHudNode extends UIRootNode {
  @attribute
  public pxPerHp: number = 0.75
  @attribute
  public pxPerStamina: number = 2.4
  @attribute
  public minBarWidth: number = 160
  @attribute
  public maxBarWidth: number = 900
  @attribute
  public noticeSeconds: number = 2.6
  /** Key shown in front of the interaction prompt. */
  @attribute
  public interactKey: string = 'E'

  private _player: Node = null
  private _w: any = {}
  private _barLeft: number = 48
  private _noticeAge: number = 99
  private _message: Node = null
  private _messageAge: number = 0

  onStart() {
    // The owner: the nearest ancestor that is a fighter (the Player the HUD is a child of).
    for (let n = this.parent; n; n = n.parent) if ((n as any).team) { this._player = n; break }
    for (const name of ['Health', 'HealthLag', 'HealthBack', 'Stamina', 'StaminaBack', 'Estus', 'Weapon', 'Souls',
      'SoulsGain', 'Prompt', 'PromptText', 'Notice', 'Message', 'MessageTitle', 'MessageBody']) {
      this._w[name] = this._find(name)
    }
    const health = this._w.Health as any
    if (health) this._barLeft = health.offsetMin[0]
    this._show('Message', false)
    this._show('Prompt', false)
    this._text('Notice', '')
    this._text('SoulsGain', '')
  }

  onUpdate(delta: number) {
    const p = this._player as any
    this._noticeAge += delta
    this._messageAge += delta

    if (p) {
      this._bar('Health', p.hp, p.maxHp)
      this._bar('HealthLag', p.hp, p.maxHp)
      this._width(['Health', 'HealthLag', 'HealthBack'], p.maxHp * this.pxPerHp)
      this._bar('Stamina', p.stamina, p.maxStamina)
      this._width(['Stamina', 'StaminaBack'], p.maxStamina * this.pxPerStamina)
      this._text('Estus', 'Estus Flask  ' + (p.estus ?? 0) + ' / ' + (p.estusMax ?? 0))
      this._text('Weapon', p.weaponName ?? '')
      this._text('Souls', String(Math.round(p.souls ?? 0)))
      this._text('SoulsGain', p.soulsGainAge < 2 && p.lastSoulsGain > 0 ? '+' + p.lastSoulsGain : '')

      const prompt = p.interactPrompt ?? ''
      this._show('Prompt', !!prompt && !this._message)
      if (prompt) this._text('PromptText', this.interactKey + '   ' + prompt)
    }

    if (this._noticeAge > this.noticeSeconds) this._text('Notice', '')

    // A message closes when the player walks out of its source's zone (closeMessageFrom), or dies.
    if (this._message && p?.isDead) this._closeMessage()
  }

  /** The character this HUD shows. */
  public get owner(): Node { return this._player }

  public showNotice(text: string): void {
    this._text('Notice', text)
    this._noticeAge = 0
  }

  /** Show a message; showing the SAME source again closes it (Interact toggles). */
  /** The player left `source`'s trigger zone: close its message if it is the one showing. */
  public closeMessageFrom(source: Node): void {
    if (this._message && this._message === source) this._closeMessage()
  }

  public showMessage(title: string, body: string, source: Node): void {
    if (this._message && this._message === source && this._messageAge > 0.15) { this._closeMessage(); return }
    this._message = source
    this._messageAge = 0
    this._text('MessageTitle', title)
    this._text('MessageBody', body)
    this._show('Message', true)
  }

  private _closeMessage(): void {
    this._message = null
    this._show('Message', false)
  }

  private _bar(name: string, value: number, max: number): void {
    const bar = this._w[name] as UIProgressBarNode
    if (!bar) return
    if (bar.max !== max) bar.max = Math.max(1, max)
    bar.value = Math.max(0, value)
  }

  private _width(names: string[], px: number): void {
    const width = Math.max(this.minBarWidth, Math.min(this.maxBarWidth, px))
    for (const name of names) {
      const node = this._w[name] as any
      if (!node) continue
      const right = node.offsetMin[0] + width
      if (Math.abs(node.offsetMax[0] - right) > 0.5) node.offsetMax = [right, node.offsetMax[1]]
    }
  }

  private _text(name: string, value: string): void {
    const node = this._w[name] as UITextNode
    if (node && node.text !== value) node.text = value
  }

  private _show(name: string, on: boolean): void {
    const node = this._w[name] as any
    if (node && node.visible !== on) node.visible = on
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — a boss's health bar. Attach to a screen-space UI Root that is a CHILD of the boss (in the
 * Hollow Warden template): the bar belongs to the boss it shows and reads that boss — its owner — every
 * frame. It shows while the boss is awake and alive, so it comes up when the fight starts and goes when
 * the boss falls. A second boss template brings its own bar; nothing in the scene has to change.
 *
 *   BossName                 uiText          the owner's `displayName`
 *   BossHealth, BossLag      uiProgressBar   HP, and the yellow bar that drains behind it
 */
export default class SoulsBossBarNode extends UIRootNode {
  private _owner: Node = null
  private _w: any = {}

  onStart() {
    for (let n = this.parent; n; n = n.parent) if ((n as any).team) { this._owner = n; break }
    for (const name of ['Bar', 'BossName', 'BossHealth', 'BossLag']) this._w[name] = this._find(name)
    this._show(false)
  }

  onUpdate(delta: number) {
    const boss = this._owner as any
    const on = !!boss && boss.isAwake && !boss.isDead && boss.fightState !== 'dormant'
    this._show(on)
    if (!on) return
    const hp = Math.max(0, boss.hp ?? 0), max = Math.max(1, boss.maxHp ?? 1)
    const name = this._w.BossName as UITextNode
    const label = boss.displayName ?? boss.name ?? ''
    if (name && name.text !== label) name.text = label
    for (const key of ['BossHealth', 'BossLag']) {
      const bar = this._w[key] as UIProgressBarNode
      if (!bar) continue
      if (bar.max !== max) bar.max = max
      bar.value = hp
    }
  }

  /** The boss this bar shows. */
  public get owner(): Node { return this._owner }

  private _show(on: boolean): void {
    const bar = this._w.Bar as any
    if (bar && bar.visible !== on) bar.visible = on
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Node, UIRootNode, UITextNode } from 'cleo'
import { child, attribute } from 'cleo/decorators'

/**
 * Hollow Keep — the big centre-screen banners: YOU DIED, BONFIRE LIT, VICTORY ACHIEVED. Attach to the
 * `Banner` node, a screen-space UI Root authored hidden, with a `Band` panel and a `BannerText` text.
 *
 * Its own root rather than part of the HUD, because setting `visible` on a node writes every descendant —
 * revealing a panel nested in the HUD would force every HUD widget visible with it.
 *
 * `showBanner(text, kind)` fades in, holds, and fades out. `kind` picks the colour: `red` (death — held
 * until `hideBanner`, which the respawn calls) or `gold`.
 */
export default class SoulsBannerNode extends UIRootNode {
  @attribute
  public fadeIn: number = 0.6
  @attribute
  public hold: number = 2.2
  @attribute
  public fadeOut: number = 1
  @attribute
  public redColor: [number, number, number] = [0.72, 0.08, 0.06]
  @attribute
  public goldColor: [number, number, number] = [0.96, 0.82, 0.46]

  @child('BannerText')
  private _text: UITextNode = null
  private _age: number = -1
  private _sticky: boolean = false

  onStart() {
    this.visible = false
  }

  public showBanner(text: string, kind: string): void {
    const c = kind === 'red' ? this.redColor : this.goldColor
    if (this._text) {
      this._text.text = text
      this._text.tint = [c[0], c[1], c[2], 1]
    }
    this._sticky = kind === 'red'
    this._age = 0
    this.opacity = 0
    this.visible = true
  }

  public hideBanner(): void {
    if (this._age < 0) return
    this._sticky = false
    this._age = Math.max(this._age, this.fadeIn + this.hold)
  }

  onUpdate(delta: number) {
    if (this._age < 0) return
    this._age += delta
    const t = this._age
    let a = 1
    if (t < this.fadeIn) a = t / this.fadeIn
    else if (this._sticky) a = 1
    else if (t > this.fadeIn + this.hold) a = 1 - (t - this.fadeIn - this.hold) / this.fadeOut
    a = Math.max(0, Math.min(1, a))
    if (Math.abs(this.opacity - a) > 0.004) this.opacity = a
    if (!this._sticky && t > this.fadeIn + this.hold + this.fadeOut) {
      this._age = -1
      this.visible = false
    }
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'
import { attribute } from 'cleo/decorators'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the level-up menu shown while resting at a bonfire. Attach to the `BonfireMenu` node, a
 * screen-space UI Root authored hidden.
 *
 *   Card
 *     Title, LevelText, SoulsText, CostText, Derived, Help       uiText
 *     Row_Vigor / Row_Endurance / Row_Strength / Row_Dexterity     uiStack rows, each with
 *        Label (uiText)  Minus (uiButton)  Value (uiText)  Plus (uiButton)
 *     Confirm, Leave                                                uiButton
 *
 * Points are allocated as PENDING and cost nothing until Confirm, so the player can try a build and back
 * out. Each point costs the souls for one more level, priced by the player's own `levelCost`, so the total
 * of several points is the sum of consecutive levels. Every number shown comes from its owner: HP and
 * stamina from the player's curves, attack rating from each weapon.
 *
 * Keyboard/gamepad (the UI map): Navigate up/down picks a stat, left/right removes/adds a point, Submit
 * confirms, Cancel leaves. The mouse can click every button. The Gameplay map is disabled while open, so
 * the same keys do not also move the character.
 */
const STATS = ['vigor', 'endurance', 'strength', 'dexterity']

export default class SoulsBonfireMenuNode extends UIRootNode {
  @attribute
  public repeatDelay: number = 0.35
  @attribute
  public repeatRate: number = 0.09
  public selectedTint: [number, number, number, number] = [0.85, 0.65, 0.3, 0.35]
  public rowTint: [number, number, number, number] = [1, 1, 1, 0.04]
  @attribute
  public isOpen: boolean = false

  private _gm: Node = null
  private _player: Node = null
  private _pending: number[] = [10, 10, 10, 10]
  private _selected: number = 0
  private _navHeld: number = 0
  private _navRepeat: number = 0
  private _navLast: number[] = [0, 0]
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const rows = ['Row_Vigor', 'Row_Endurance', 'Row_Strength', 'Row_Dexterity']
    rows.forEach((name, i) => {
      const row = this._find(name)
      if (!row) return
      const minus = this._find('Minus', row) as UIButtonNode
      const plus = this._find('Plus', row) as UIButtonNode
      if (minus) minus.onPress = () => { this._selected = i; this._adjust(-1) }
      if (plus) plus.onPress = () => { this._selected = i; this._adjust(1) }
    })
    const confirm = this._find('Confirm') as UIButtonNode
    if (confirm) confirm.onPress = () => this._confirm()
    const leave = this._find('Leave') as UIButtonNode
    if (leave) leave.onPress = () => this.close()
  }

  /** Called by the manager when the player rests. */
  public open(gm: Node, player: Node, bonfire: Node): void {
    this._gm = gm
    this._player = player
    this._resetPending()
    this._selected = 0
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    this._refresh()
  }

  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    ;(this._gm as any)?.leaveBonfire?.()
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return

    const nav = Input.vector('Navigate')
    const dy = Math.abs(nav[1]) > 0.5 ? Math.sign(nav[1]) : 0
    const dx = Math.abs(nav[0]) > 0.5 ? Math.sign(nav[0]) : 0
    const fresh = dy !== this._navLast[1] || dx !== this._navLast[0]
    this._navLast = [dx, dy]
    let step = false
    if (dx || dy) {
      if (fresh) { step = true; this._navHeld = 0; this._navRepeat = 0 }
      else {
        this._navHeld += delta
        if (this._navHeld > this.repeatDelay) {
          this._navRepeat += delta
          if (this._navRepeat >= this.repeatRate) { this._navRepeat = 0; step = true }
        }
      }
    }
    if (step) {
      // Navigate Y is positive UP; rows run top to bottom.
      if (dy) this._selected = (this._selected - dy + 4) % 4
      if (dx) this._adjust(dx)
      this._refresh()
    }

    if (Input.started('Submit')) this._confirm()
    if (Input.started('Cancel')) this.close()
  }

  // ----- the maths --------------------------------------------------------------------------------

  /** Souls to buy every pending point, from the player's CURRENT level. */
  public pendingCost(): number {
    const p = this._player as any
    if (!p?.levelFor) return 0
    const from = p.level
    const to = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    let cost = 0
    for (let l = from; l < to; l++) cost += p.levelCost(l)
    return cost
  }

  private _adjust(delta: number): void {
    const p = this._player as any
    if (!p) return
    const key = STATS[this._selected]
    const floor = p[key]
    const next = this._pending[this._selected] + delta
    if (next < floor || next > 99) return
    const before = this._pending[this._selected]
    this._pending[this._selected] = next
    if (delta > 0 && this.pendingCost() > (p.souls ?? 0)) {
      this._pending[this._selected] = before
      playSound(this, 'Menu Deny')
      return
    }
    playSound(this, 'Menu Tick')
    this._refresh()
  }

  private _confirm(): void {
    const p = this._player as any
    if (!p) return
    const cost = this.pendingCost()
    if (cost <= 0) return
    if (p.applyLevelUp?.(this._pending[0], this._pending[1], this._pending[2], this._pending[3], cost)) {
      playSound(this, 'Level Up')
      ;(this._gm as any)?.notice?.('Level up!')
    }
    this._resetPending()
    this._refresh()
  }

  private _resetPending(): void {
    const p = this._player as any
    this._pending = STATS.map(k => (p ? p[k] : 10))
  }

  private _refresh(): void {
    const p = this._player as any
    if (!p?.levelFor) return
    const level = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    const cost = this.pendingCost()
    this._set('LevelText', 'Level  ' + p.level + (level !== p.level ? '  ->  ' + level : ''))
    this._set('SoulsText', 'Souls  ' + p.souls + (cost ? '  ->  ' + (p.souls - cost) : ''))
    this._set('CostText', 'Next level  ' + p.levelCost(level) + ' souls')

    const labels = ['Vigor', 'Endurance', 'Strength', 'Dexterity']
    labels.forEach((label, i) => {
      const row = this._find('Row_' + label) as any
      if (!row) return
      const changed = this._pending[i] !== p[STATS[i]]
      const value = this._find('Value', row) as UITextNode
      if (value) value.text = String(this._pending[i]) + (changed ? ' *' : '')
      const tint = i === this._selected ? this.selectedTint : this.rowTint
      row.tint = [tint[0], tint[1], tint[2], tint[3]]
    })

    const weapons: Node[] = p.weapons?.() ?? []
    const ar = weapons.map(w => (w as any).displayName + ' ' + ((w as any).attackRating?.(this._pending[2], this._pending[3]) ?? 0))
    this._set('Derived', 'HP ' + p.hpForVigor(this._pending[0]) + '    Stamina ' + p.staminaForEndurance(this._pending[1])
      + '\nAttack  ' + ar.join('   '))
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node && node.text !== text) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(root)
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'
import { attribute } from 'cleo/decorators'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * A yes/no question over the game: "Enter the skull cave?". Attach to the `ConfirmDialog` node, a
 * screen-space UI Root authored hidden, on the player beside the bonfire menu:
 *
 *   ConfirmDialog
 *     Card
 *       Title, Body      uiText
 *       Yes, No          uiButton
 *
 * `ask(title, body, onYes)` opens it. Submit or Yes answers yes, Cancel or No answers no; the mouse can
 * click either. Gameplay input is off while it is open, and back on before `onYes` runs -- a scene
 * switch keeps the input maps as they are, so a dialog that loaded a scene while still holding Gameplay
 * off would leave the next scene unable to move.
 */
export default class SoulsConfirmDialogNode extends UIRootNode {
  @attribute
  public isOpen: boolean = false

  private _onYes: () => void = null
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const yes = this._find('Yes') as UIButtonNode
    if (yes) yes.onPress = () => this._answer(true)
    const no = this._find('No') as UIButtonNode
    if (no) no.onPress = () => this._answer(false)
  }

  public ask(title: string, body: string, onYes: () => void): void {
    this._set('Title', title)
    this._set('Body', body)
    this._onYes = onYes
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    playSound(this, 'Menu Tick')
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return
    if (Input.started('Submit')) this._answer(true)
    else if (Input.started('Cancel')) this._answer(false)
  }

  private _answer(yes: boolean): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    const then = this._onYes
    this._onYes = null
    if (yes) then?.()
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    for (const child of root.children) {
      if (child.name === name) return child
      const found = this._find(name, child)
      if (found) return found
    }
    return null
  }
}

import { Game, Input, Logger, Node, SaveGame, UIButtonNode, UIRootNode } from 'cleo'
import { find, attribute } from 'cleo/decorators'

/**
 * Hollow Keep — the pause menu. Attach to the `PauseMenu` node, a screen-space UI Root authored hidden,
 * a child of the Player like the HUD and the bonfire menu.
 *
 *   Card
 *     Title                "PAUSED"                                 uiText
 *     Resume               back to the game                          uiButton
 *     Bonfire              return to the last bonfire rested at      uiButton
 *     Load                 load the game saved at the last rest      uiButton (disabled with no save)
 *     Hint                 the controls line                         uiText
 *
 * Pause (P, Escape, or Start on a pad — the UI map) opens it: the game is paused with `Game.pause()`, so
 * physics, scripts, timers and animation all stop where they are. Pause or Cancel closes it; the mouse
 * can click either button.
 *
 * It listens in a LATE UPDATE (`scene.addLateUpdate`), not in onUpdate: while the game is paused no node's
 * onUpdate runs, so a menu that polled there could open but never close. Late updates run every frame,
 * paused or not, and input is read every frame too.
 *
 * It never opens over another menu (resting at a bonfire, a yes/no dialog) or while the player is dying,
 * nor in the moment just after one closes: Escape is also the bonfire menu's Cancel, and the press that
 * closes that menu must not open this one.
 */
export default class SoulsPauseMenuNode extends UIRootNode {
  /** Real seconds after another menu closes during which Pause is ignored (see above). */
  @attribute
  public reopenGuard: number = 0.25
  @attribute
  public isOpen: boolean = false

  @find('GameManager')
  private _gm: Node = null
  @find('Player')
  private _player: Node = null
  private _menus: Node[] = []
  private _stopListening: (() => void) | null = null
  /** Real time (seconds), counted in the late update, and when another menu was last seen open. */
  private _clock: number = 0
  private _otherMenuAt: number = -1

  onStart() {
    this.visible = false
    this.isOpen = false
    // The other menus this must not open over: the bonfire menu and the yes/no dialog.
    this._menus = [
      this._player?.getChildByName('BonfireMenu')[0],
      this._player?.getChildByName('ConfirmDialog')[0],
      this.findNode('ConfirmDialog'),
    ].filter(n => !!n && n !== this)
    const resume = this._find('Resume') as UIButtonNode
    if (resume) resume.onPress = () => this.close()
    const bonfire = this._find('Bonfire') as UIButtonNode
    if (bonfire) bonfire.onPress = () => this._toBonfire()
    const load = this._find('Load') as UIButtonNode
    if (load) load.onPress = () => this._loadLastRest()
    this._stopListening = this.scene?.addLateUpdate((_delta, unscaled) => this._listen(unscaled)) ?? null
  }

  onDespawn() {
    this._stopListening?.()
    this._stopListening = null
    if (this.isOpen) this.close()
  }

  /** Pause the game and show the menu. */
  public open(): void {
    if (this.isOpen) return
    this.isOpen = true
    this.visible = true
    Game.clearSlowMotion()
    Game.pause()
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    // Load last rest only when there is a save to load.
    const load = this._find('Load') as UIButtonNode
    if (load) {
      load.disabled = true
      if (SaveGame.available) SaveGame.exists('auto').then(ok => { load.disabled = !ok }).catch(() => {})
    }
  }

  /** Hide the menu and carry on. */
  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Game.resume()
    // Another menu may have been opened underneath by a script; it keeps the Gameplay map off.
    if (!this._otherMenuOpen()) Input.enableMap('Gameplay')
    this._otherMenuAt = this._clock
  }

  private _listen(unscaled: number): void {
    this._clock += unscaled
    if (this._otherMenuOpen()) this._otherMenuAt = this._clock
    if (this.isOpen) {
      if (Input.started('Pause') || Input.started('Cancel')) this.close()
      else if (Input.started('Submit')) this.close()
      return
    }
    if (!Input.started('Pause') || !this._canPause()) return
    this.open()
  }

  private _canPause(): boolean {
    if (Game.isPaused) return false                        // paused by someone else (the editor)
    if (this._otherMenuOpen()) return false
    if (this._clock - this._otherMenuAt < this.reopenGuard) return false
    const p = this._player as any
    if (p?.isDead) return false
    return true
  }

  private _otherMenuOpen(): boolean {
    return this._menus.some(m => (m as any).isOpen)
  }

  private _toBonfire(): void {
    this.close()
    ;(this._gm as any)?.respawnAtBonfire?.()
  }

  /** Load the game as it was saved at the last bonfire: the world, and the player at that bonfire. */
  private _loadLastRest(): void {
    this.close()
    const gm = this._gm as any
    if (!gm?.loadLastRest) return
    gm.loadLastRest()
      .then((loaded: boolean) => { if (!loaded) gm.notice?.('Nothing saved yet: rest at a bonfire') })
      .catch((e: any) => Logger.warn(`Hollow Keep: the save could not be loaded: ${e?.message ?? e}`, 'Script'))
  }

  private _find(name: string, under: Node = this): Node {
    for (const child of under.children) {
      if (child.name === name) return child
      const deeper = this._find(name, child)
      if (deeper) return deeper
    }
    return null
  }
}

import type { Node } from 'cleo'

/**
 * Hollow Keep — shared maths for the Souls* scripts. A script MODULE: it exports helpers and is never
 * attached to a node. Every script that needs these imports them by path:
 *
 *   import { num, yawTo, angleDiff } from '@/Core/Scripts/SoulsMath'
 *
 * (the project-root form; a path relative to the importing script works too).
 *
 * Evaluated once per game and shared, so it holds no per-node state.
 *
 * Angles follow the engine's convention: yaw in degrees, 0 is +Z, counter-clockwise positive (the
 * character's RIGHT is a negative turn).
 */

/** `value` if it is a finite number, else `fallback` — for reading tunables off other scripts' nodes. */
export function num(value: any, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback
}

export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v
}

/** Distance on the ground plane, ignoring height. */
export function planarDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.hypot(b[0] - a[0], b[2] - a[2])
}

/** World yaw in degrees from `a` toward `b`. */
export function yawTo(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.atan2(b[0] - a[0], b[2] - a[2]) * 180 / Math.PI
}

/** Signed shortest difference `a - b` in degrees, in (-180, 180]. */
export function angleDiff(a: number, b: number): number {
  let d = (a - b) % 360
  if (d > 180) d -= 360
  else if (d <= -180) d += 360
  return d
}

/** The yaw a node faces, from its world forward. */
export function forwardYaw(node: Node): number {
  const f = node.worldForward
  return Math.atan2(f[0], f[2]) * 180 / Math.PI
}

/**
 * How much a stat adds to a weapon that scales with it fully: 0 at 10, 0.6 at 30, 0.9 at 50, then a
 * quarter of a percent per point. Soft caps are the whole reason a build has to choose.
 */
export function statBonus(stat: number): number {
  if (stat <= 10) return 0
  if (stat <= 30) return (stat - 10) / 20 * 0.6
  if (stat <= 50) return 0.6 + (stat - 30) / 20 * 0.3
  return 0.9 + (stat - 50) * 0.0025
}

import { Node, resolveSocketOwner } from 'cleo'
import { num } from '@/Core/Scripts/SoulsMath'

/**
 * Hollow Keep — hitboxes and hurtboxes. A script MODULE (never attached to a node), shared by the
 * player, the enemies, the bolt and the breakables.
 *
 * Both are TRIGGER VOLUMES, separate from the rigid bodies characters walk with, and the engine reports
 * when one enters the other (a trigger that `detectTriggers`; see Trigger in the engine). With the eye
 * menu's Triggers ▸ Runtime on, Play draws them live: the blade's hitbox appears on `hit` and vanishes on
 * `hitEnd`, and a rolling player's hurtbox blinks out for exactly its i-frames.
 *
 * ## Hurtboxes
 *
 * A child node named `Hurtbox` of each character (and breakable), carrying one capsule trigger in its
 * team's layer (`LAYER.PLAYER_HURTBOX` / `LAYER.ENEMY_HURTBOX`) that detects only hitboxes. The
 * generator authors it the size of the walking capsule; a character without one gets one built from its
 * body on its first frame. `hurtboxActive` false switches it OFF — that is what i-frames ARE: a roll does
 * not make the player "ignore" a hit, for those frames there is nothing there to hit.
 *
 * ## Hitboxes
 *
 * A weapon's hitbox is a capsule along its blade, from `bladeStart` to `bladeEnd` with `bladeRadius`,
 * measured in the weapon's `Mesh` child space — the same space the blade's boxes are modelled in, so
 * re-gripping or swapping the mesh carries the hitbox with it. It is a `Hitbox` child of the `Mesh`,
 * made the first time the weapon swings, and switched on by the attack's clip events: `hit` arms it
 * (`openSwing`), `hitEnd` disarms it (`closeSwing`). It is CONTINUOUS — tested along its path from last
 * frame to this one — so a fast swing cannot pass through an arm between two frames. Each target is hit
 * once per swing.
 *
 * ## Swing blockers
 *
 * A solid body whose node has the variable `blocksSwings` = true (walls, pillars, gates) stops a swing
 * that reaches it before any enemy: the blade bounces, and the attacker recoils. Walls are not triggers,
 * so while a window is open the blade is also swept against blockers alone, over the same frame's path.
 * Floors are not swing blockers, so an overhead never bounces off the ground.
 */

/**
 * The collision layers (trigger group/mask bits) of the combat volumes. Layer 1 is every ordinary body and
 * 2 the ragdoll bones; these stay clear of both, so a hurtbox never even reaches a contact test with its
 * own character's capsule.
 */
export const LAYER = { PLAYER_HURTBOX: 1 << 8, ENEMY_HURTBOX: 1 << 9, HITBOX: 1 << 10 }

/** The hurtbox layer of a team ('player' or 'enemy'). */
export function hurtboxLayer(team: string): number {
  return team === 'player' ? LAYER.PLAYER_HURTBOX : LAYER.ENEMY_HURTBOX
}

export interface Capsule { a: number[]; b: number[]; radius: number }

/** One hurtbox the armed hitbox entered: where, and how far through that frame's sweep (0..1). */
export interface HitboxContact { node: Node; point: number[] | null; fraction: number }

/** The swing state an attacker keeps between frames. Reset with `openSwing` when a window opens. */
export interface Swing {
  /** Last frame's blade, or null on the window's first frame. For the blocker sweep. */
  prev: Capsule | null
  /** Every node this swing has already damaged. */
  hit: Node[]
  open: boolean
  /** The weapon whose hitbox is armed for this window, and the remover of its contact listener. */
  weapon: Node | null
  off: (() => void) | null
  /** What the armed hitbox entered since the last `stepSwing`, as physics reported it. */
  pending: HitboxContact[]
}

export function newSwing(): Swing { return { prev: null, hit: [], open: false, weapon: null, off: null, pending: [] } }

/**
 * Open an active window (the `hit` event). With a `weapon` — only pass one that is in the attacker's own
 * hand, see wieldedBy — its hitbox is switched on against `target`'s hurtboxes (the TEAM being attacked:
 * 'enemy' for the player's blade, 'player' for an enemy's) and starts collecting contacts.
 */
export function openSwing(swing: Swing, weapon: Node | null = null, target: 'player' | 'enemy' = 'enemy'): void {
  closeSwing(swing)
  swing.hit.length = 0
  swing.open = true
  if (!weapon) return
  const trigger = armHitbox(weapon, target)
  if (!trigger) return
  swing.weapon = weapon
  swing.off = trigger.onContact((c: any) => {
    if (c.phase === 'enter' && swing.open && c.node) swing.pending.push({ node: c.node, point: c.point, fraction: c.fraction })
  })
}

/** Close the window (the `hitEnd` event, a fallback timer, a state change): the hitbox switches off. */
export function closeSwing(swing: Swing): void {
  swing.prev = null
  swing.open = false
  swing.off?.()
  swing.off = null
  if (swing.weapon) disarmHitbox(swing.weapon)
  swing.weapon = null
  swing.pending.length = 0
}

/** Transform a point by a column-major 4x4 matrix. */
function transformPoint(m: ArrayLike<number>, p: ArrayLike<number>): number[] {
  const x = p[0], y = p[1], z = p[2]
  return [m[0] * x + m[4] * y + m[8] * z + m[12], m[1] * x + m[5] * y + m[9] * z + m[13], m[2] * x + m[6] * y + m[10] * z + m[14]]
}

/** A weapon field: a script field (SoulsWeapon), or a plain node VARIABLE (a script-less weapon). */
function field(weapon: Node, name: string): any {
  return (weapon as any)[name] ?? (weapon as any).getVariable?.(name)
}

/** The space the blade fields are measured in: the weapon's `Mesh` child, else the weapon itself. */
function bladeSpace(weapon: Node): Node {
  return weapon.getChildByName?.('Mesh')?.[0] ?? weapon
}

/**
 * The weapon's blade capsule in world space, or null when it has none. Read from the `Mesh` child's world
 * transform (falling back to the weapon node itself), so the radius scales with a big enemy's weapon.
 */
export function bladeCapsule(weapon: Node): Capsule | null {
  if (!weapon) return null
  const start = field(weapon, 'bladeStart'), end = field(weapon, 'bladeEnd')
  if (!start || !end || start.length < 3 || end.length < 3) return null
  const m = bladeSpace(weapon).worldTransform as ArrayLike<number>
  const scale = Math.hypot(m[0], m[1], m[2])
  return { a: transformPoint(m, start), b: transformPoint(m, end), radius: num(field(weapon, 'bladeRadius'), 0.1) * scale }
}

// =====================================================================================================
// Hitboxes
// =====================================================================================================

const HITBOX = 'Hitbox'

/**
 * The weapon's hitbox trigger, made on first use: a `Hitbox` child of its `Mesh` holding a capsule along
 * the blade. Reshaped when the blade fields or the mesh's scale change (a weapon re-gripped, a big enemy's
 * club), never otherwise. Null for a weapon with no blade.
 */
export function weaponHitbox(weapon: Node): any {
  if (!weapon) return null
  const start = field(weapon, 'bladeStart'), end = field(weapon, 'bladeEnd')
  if (!start || !end || start.length < 3 || end.length < 3) return null
  const space = bladeSpace(weapon)
  let node = space.getChildByName(HITBOX)[0] as any
  if (!node) {
    node = new Node(HITBOX)
    space.addChild(node)
  }
  // The trigger lives in the Hitbox node's space, which is the mesh's minus its scale: physics places
  // triggers by position and rotation only, so the scale goes into the shape.
  const m = space.worldTransform as ArrayLike<number>
  const scale = Math.hypot(m[0], m[1], m[2]) || 1
  const radius = num(field(weapon, 'bladeRadius'), 0.1)
  const key = `${start.join(',')}|${end.join(',')}|${radius}|${scale.toFixed(4)}`
  if (!node.trigger || node._bladeKey !== key) {
    const trigger = node.trigger ?? node.setTrigger({ enabled: false, continuous: true, detectTriggers: true, group: LAYER.HITBOX, mask: 0 })
    trigger.setCapsule([start[0] * scale, start[1] * scale, start[2] * scale], [end[0] * scale, end[1] * scale, end[2] * scale], radius * scale)
    node._bladeKey = key
  }
  return node.trigger
}

/** Switch the weapon's hitbox on against `target`'s hurtboxes. Returns its trigger, or null (no blade). */
export function armHitbox(weapon: Node, target: 'player' | 'enemy'): any {
  const trigger = weaponHitbox(weapon)
  if (!trigger) return null
  trigger.mask = hurtboxLayer(target)
  trigger.enabled = true
  return trigger
}

/** Switch the weapon's hitbox off (if it has one). */
export function disarmHitbox(weapon: Node): void {
  const node = bladeSpace(weapon)?.getChildByName?.(HITBOX)?.[0] as any
  if (node?.trigger) node.trigger.enabled = false
}

// =====================================================================================================
// Hurtboxes
// =====================================================================================================

const HURTBOX = 'Hurtbox'

/** The `Hurtbox` child of a character or breakable, or null. */
export function hurtboxOf(owner: Node): any {
  return owner?.getChildByName?.(HURTBOX)?.[0] ?? null
}

/**
 * The owner's hurtbox, built from its body when the template has none: a capsule as tall and as wide as
 * the body's bounds, in the layer of the owner's `team`. Null for an owner with no body.
 */
export function ensureHurtbox(owner: Node): any {
  const existing = hurtboxOf(owner)
  if (existing?.trigger) return existing
  const body = (owner as any).body
  if (!body) return null
  const [lx, ly, lz, hx, hy, hz] = body.getAabb([0, 0, 0, 0, 0, 0])
  const radius = Math.max(0.05, Math.min(hx - lx, hz - lz) / 2)
  const base = owner.worldPosition
  const bottom = ly - base[1], top = hy - base[1]
  const node = existing ?? new Node(HURTBOX)
  if (!existing) owner.addChild(node)
  node.setTrigger({ group: hurtboxLayer((owner as any).team), mask: LAYER.HITBOX, detectTriggers: true })
    .setCapsule([0, bottom + radius, 0], [0, Math.max(bottom + radius, top - radius), 0], radius)
  return node
}

/** Switch the owner's hurtbox on or off; only touches it on a change. */
export function setHurtboxEnabled(owner: Node, on: boolean): void {
  const trigger = hurtboxOf(owner)?.trigger
  if (trigger && trigger.enabled !== on) trigger.enabled = on
}

/**
 * The character (or breakable) a hurtbox belongs to: the nearest node at or above it that takes hits. A
 * character's Collider (what a ray or a sweep reports for its body) stands for the character in it.
 */
export function characterOf(node: Node): Node | null {
  for (let n: Node = node?.character ?? node; n; n = n.parent) if (typeof (n as any).receiveHit === 'function') return n
  return null
}

// =====================================================================================================
// Who may hit whom
// =====================================================================================================

function isWithin(node: Node, ancestor: Node): boolean {
  for (let n: Node = node; n; n = n.parent) if (n === ancestor) return true
  return false
}

/**
 * Whether `weapon` is actually in `wielder`'s hand: pinned to a socket that resolves on a model INSIDE the
 * wielder. A weapon's hitbox is only armed when it is.
 *
 * The safety net under a model swap: a character whose new rig has no hand socket used to have its weapon
 * ride whichever model in the scene did have one, and its swings landed there — a sword hurting a
 * knight across the level, enemy blades never reaching the player. A weapon not in its wielder's hand now
 * simply hits nothing.
 */
export function wieldedBy(weapon: Node, wielder: Node): boolean {
  if (!weapon || !wielder) return false
  const attachment = (weapon as any).socketAttachment
  // Unpinned (a user's own weapon parented straight to a bone node): it is the wielder's if it is under it.
  if (!attachment) return isWithin(weapon, wielder)
  const owner: any = resolveSocketOwner(weapon, attachment, (id: string) => weapon.scene?.getNodeById(id) ?? null)
  return !!owner && isWithin(owner, wielder) && (owner.socketNames ?? []).includes(attachment.socket)
}

/**
 * Whether `node` (a character, or a breakable) is a live target `attacker` may hit. `kind` is the TEAM
 * being attacked (a fighter's `team` field, SoulsCharacter): the player's blade hits 'enemy', an enemy's
 * hits 'player'.
 */
export function isHurtbox(node: Node, attacker: Node, kind: 'player' | 'enemy'): boolean {
  const n = node as any
  if (!node || node === attacker || n.isDead || n.hurtboxActive === false || n.spawned === false) return false
  return n.team === kind && typeof n.receiveHit === 'function'
}

/**
 * Whether a body stops a swing: solid, and its node opted in with the `blocksSwings` variable. The body's
 * node is a Collider; the variable may also be on a node directly in it (a placed model wrapped in one).
 */
export function blocksSwings(node: Node, body: any): boolean {
  if (!node || !body || body.isTrigger || body.collisionResponse === false) return false
  const flagged = (n: Node) => !!(n as any).getVariable?.('blocksSwings')
  return flagged(node) || (node.nodeType === 'collider' && node.children.some(flagged))
}

/**
 * Overlap/sweep options that find only `team`'s hurtboxes, mapped back to the targets they belong to by
 * `hurtboxTargets`. For a slam or a bolt: a switched-off hurtbox (a roll's i-frames) is never found.
 */
export function hurtboxQuery(team: 'player' | 'enemy', attacker: Node | null): any {
  return {
    includeTriggers: true,
    layerMask: hurtboxLayer(team),
    ignore: attacker,
    filter: (node: Node) => { const target = characterOf(node); return !!target && target !== attacker && isHurtbox(target, attacker, team) },
  }
}

/** A query's hits as the targets they hurt, each once, in the order the query reached them. */
export function hurtboxTargets(hits: { node: Node; point: number[] }[]): { node: Node; point: number[] }[] {
  const out: { node: Node; point: number[] }[] = []
  for (const h of hits) {
    const target = characterOf(h.node)
    if (target && !out.some(o => o.node === target)) out.push({ node: target, point: h.point })
  }
  return out
}

export interface SwingContact {
  /** New targets reached this frame, in the order the blade reached them. */
  targets: { node: Node; point: number[] }[]
  /** Where the blade met a swing blocker BEFORE any of those targets, or null. */
  blockedAt: number[] | null
}

/**
 * Advance a swing by one frame: take the hurtboxes its hitbox entered (physics reported them at the start
 * of this frame, for the blade's path from two frames ago to last frame), sweep that same path against
 * swing blockers, and report the new targets and whether a blocker got in the way first. Targets already
 * hit this swing are not reported again. With `bounces` false, blockers are ignored (a heavy slam ploughs
 * on through).
 */
export function stepSwing(physics: any, swing: Swing, blade: Capsule, attacker: Node,
  kind: 'player' | 'enemy', bounces: boolean): SwingContact {
  const result: SwingContact = { targets: [], blockedAt: null }
  if (!swing.open) return result

  const reached: HitboxContact[] = []
  for (const c of swing.pending.splice(0)) {
    const target = characterOf(c.node)
    if (!target || !isHurtbox(target, attacker, kind) || swing.hit.includes(target) || reached.some(r => r.node === target)) continue
    const p = target.worldPosition
    reached.push({ node: target, point: c.point ?? [p[0], p[1], p[2]], fraction: c.fraction })
  }
  reached.sort((a, b) => a.fraction - b.fraction)

  // The blockers, over the same path. On the window's first frame the path is the blade where it is.
  let blockedFraction = Infinity
  if (bounces && physics && blade) {
    const prev = swing.prev ?? blade
    const hits = physics.sweepCapsule(prev.a, prev.b, blade.a, blade.b, blade.radius, {
      ignore: attacker, filter: (node: Node, body: any) => blocksSwings(node, body),
    }) as { node: Node; point: number[]; fraction: number }[]
    if (hits.length) { blockedFraction = hits[0].fraction; result.blockedAt = hits[0].point }
  }
  if (blade) swing.prev = blade

  // Targets the blade reached before the wall still take the hit; the ones after it are spared.
  for (const r of reached) {
    if (r.fraction > blockedFraction) break
    swing.hit.push(r.node)
    result.targets.push({ node: r.node, point: r.point as number[] })
  }
  return result
}

import type { Node } from 'cleo'

/**
 * Hollow Keep — sound cues. A script MODULE: every template that makes a sound OWNS it, as a SoundNode
 * child of a `Sounds` group in its own tree (the Player's swings, an enemy's roar, a lever's clank). A
 * script plays a cue by name and the nearest owner up its ancestry answers:
 *
 *   import { playSound } from '@/Core/Scripts/SoulsAudio'
 *   playSound(this, 'Lever')
 *
 * So a script deep inside a template (the Player's bonfire menu, an enemy's attack) plays its owner's
 * cues, and a template placed in any scene brings its sounds with it. A missing cue is silent.
 */

/** Name of the group, directly under an owner, that holds its SoundNodes. */
export const SOUNDS_GROUP = 'Sounds'

/** The SoundNode named `name` in the `Sounds` group of `from` or its nearest ancestor that has one. */
export function soundOf(from: Node, name: string): Node {
  if (!name) return null
  for (let n: Node = from; n; n = n.parent) {
    const group = n.getChildByName(SOUNDS_GROUP)[0]
    if (group) return group.getChildByName(name)[0] ?? null
  }
  return null
}

/** Play the cue `name` owned by `from` (or an ancestor). Silent when there is none. */
export function playSound(from: Node, name: string): void {
  const sound = soundOf(from, name) as any
  sound?.play?.()
}

/** Stop the cue `name` owned by `from` (or an ancestor). */
export function stopSound(from: Node, name: string): void {
  const sound = soundOf(from, name) as any
  sound?.stop?.()
}

/**
 * Play a cue whose owner is about to be REMOVED (a bolt hitting a wall): a despawned SoundNode stops,
 * so the cue is moved to the scene root where it is, plays there, and removes itself after `seconds`.
 */
export function playDetached(from: Node, name: string, seconds: number = 4): void {
  const sound = soundOf(from, name) as any
  const root = from?.scene?.root
  if (!sound || !root) return
  const at = Array.from(sound.worldPosition as ArrayLike<number>)
  root.addChild(sound)
  sound.setPosition([at[0], at[1], at[2]])
  sound.play?.()
  sound.after(seconds, () => { try { sound.remove() } catch { /* already gone */ } })
}

import { Node } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Valley — a fire's light: torches, braziers, fire pits, candles, the bonfire. Attach to the fire's root;
 * it finds its parts by type, so any layout works:
 *
 *   Torch                 this script
 *   ├── Flame             animated sprite(s), following the Light
 *   ├── Ignition          optional: an animated sprite played ONCE as the fire is lit (the bonfire's)
 *   ├── Embers            particle system(s), following the Light
 *   └── Light             point light, flickering
 *
 * - FLICKER is the engine's, not this script's: the light's own Flicker (PunctualLight.flickerAmount)
 *   wanders its intensity, and the flames and embers burn on the same beat through their Follow Light.
 *   Intensity only, so a shadowed torch keeps its cached shadow map.
 * - NO DAY AND NIGHT. The light keeps its real lumens around the clock; the camera's auto exposure is what
 *   makes it vanish in sunlight and carry the road at night.
 *
 * `lit` puts the fire out and lights it again: flames hidden, embers stopped, light off. The bonfire's
 * script drives it (its `Fire` child is one of these), so an unlit bonfire is a cold one.
 *
 * LIGHTING IT, when the fire has an `Ignition` sprite (a non-looping flipbook of the fire catching, baked
 * with the FX Creator): the ignition plays from its first frame, the light flares up with it and settles,
 * the embers start at once, the smoke thickens over the whole of it, and the burning flames fade in over
 * its last `ignitionBlend` seconds while the ignition fades out, so the flare settles into the loop. A
 * fire that STARTS lit (a torch, a bonfire already lit when the scene opens) just burns.
 */
export default class ValleyFireLightNode extends Node {
  /** Burning or not. */
  @attribute
  public lit: boolean = true
  /** Seconds, at the end of the ignition, over which the burning flames take over from it. */
  @attribute
  public ignitionBlend: number = 0.5
  /** The light's peak as the fire catches, over its full intensity. */
  @attribute
  public ignitionFlare: number = 1.4
  /** Seconds into the ignition the flare peaks. */
  @attribute
  public ignitionFlareTime: number = 0.25

  private _lights: { node: any, intensity: number }[] = []
  private _visuals: any[] = []
  private _sprites: { node: any, opacity: number, smoke: boolean }[] = []
  private _ignition: any = null
  private _shown: boolean = true
  /** Seconds into the ignition, or -1 when none is playing. */
  private _igniting: number = -1
  private _ignitionLength: number = 0

  onStart() {
    const walk = (n: any) => {
      const type = n.nodeType
      if (type === 'light' && n.light) this._lights.push({ node: n, intensity: n.light.intensity })
      else if (type === 'animatedSprite' && n.name === 'Ignition') this._ignition = n
      else if (type === 'sprite' || type === 'animatedSprite' || type === 'particleSystem') {
        this._visuals.push(n)
        if (n.sprite) this._sprites.push({ node: n, opacity: n.sprite.opacity, smoke: n.name === 'Smoke' })
      }
      for (const c of n.children ?? []) walk(c)
    }
    for (const c of this.children) walk(c)
    if (this._ignition) {
      this._ignition.visible = false
      const frames = this._ignition.frames?.length ?? 0
      this._ignitionLength = frames > 0 ? frames / Math.max(1e-3, this._ignition.fps ?? 30) : 0
    }
  }

  onUpdate(delta: number) {
    if (this.lit !== this._shown) {
      // Lit from out: the fire catches. Put out, or lit with no ignition sprite: it just changes.
      const catches = this.lit && !this._shown && this._ignition && this._ignitionLength > 0
      this._show(this.lit)
      if (catches) this._ignite()
      else this._endIgnition()
    }
    if (this._igniting >= 0) this._stepIgnition(delta)
  }

  private _show(lit: boolean): void {
    this._shown = lit
    for (const l of this._lights) l.node.light.intensity = lit ? l.intensity : 0
    for (const node of this._visuals) {
      if (node.nodeType === 'particleSystem') { if (lit) node.play?.(); else node.stop?.(true) }
      else node.visible = lit
    }
  }

  private _ignite(): void {
    this._igniting = 0
    const ignition = this._ignition
    ignition.reset?.()
    ignition.currentFrame = 0
    ignition.sprite.opacity = 1
    ignition.visible = true
    this._stepIgnition(0)
  }

  private _stepIgnition(delta: number): void {
    const t = (this._igniting += delta)
    const length = this._ignitionLength
    if (t >= length) { this._endIgnition(); return }
    // The burning flames take over across the last `ignitionBlend` seconds; the smoke builds all along.
    const blend = Math.min(Math.max(0.05, this.ignitionBlend), length)
    const handover = Math.min(1, Math.max(0, (t - (length - blend)) / blend))
    const build = t / length
    for (const s of this._sprites) s.node.sprite.opacity = s.opacity * (s.smoke ? build : handover)
    this._ignition.sprite.opacity = 1 - handover
    // The light: up to the flare at `ignitionFlareTime`, then down to its full intensity by the end.
    const peak = Math.max(1e-3, Math.min(this.ignitionFlareTime, length * 0.5))
    const scale = t < peak
      ? this.ignitionFlare * smooth(t / peak)
      : 1 + (this.ignitionFlare - 1) * (1 - smooth((t - peak) / Math.max(1e-3, length - peak)))
    for (const l of this._lights) l.node.light.intensity = l.intensity * scale
  }

  /** The ignition over (or cut short): the fire as it burns, the ignition hidden for next time. */
  private _endIgnition(): void {
    if (this._igniting < 0) return
    this._igniting = -1
    for (const s of this._sprites) s.node.sprite.opacity = s.opacity
    if (this._ignition) this._ignition.visible = false
    if (this._shown) for (const l of this._lights) l.node.light.intensity = l.intensity
  }
}

/** Smoothstep on 0..1. */
function smooth(x: number): number {
  const t = Math.min(1, Math.max(0, x))
  return t * t * (3 - 2 * t)
}

import { Game, Input, Logger, Node, SaveGame, UIButtonNode, UIRootNode } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Hollow Keep — the title menu: Continue from the last bonfire, or start a new game. Attach to the `TitleMenu`
 * node, a screen-space UI Root authored hidden, a child of the Player like the other menus.
 *
 *   Backdrop
 *     Card
 *       Title       "HOLLOW KEEP"                              uiText
 *       Continue    load the game saved at the last bonfire     uiButton
 *       New Game    start again from the beginning               uiButton
 *       Hint        the controls line                            uiText
 *
 * It shows only when there is a bonfire save to go back to and this session did not begin from one: a first
 * game starts at once, and so does a game the menu already let through (the `started` global, which every
 * save carries). While it shows, the game is paused. Navigate up/down picks, Submit confirms; the mouse can
 * click either button.
 *
 * Like the pause menu it listens in a LATE UPDATE, which runs while the game is paused.
 */
export default class SoulsTitleMenuNode extends UIRootNode {
  /** The slot Continue loads: the one the bonfires save to (GameManager.saveSlot). */
  @attribute
  public slot: string = 'auto'
  @attribute
  public isOpen: boolean = false

  private _buttons: UIButtonNode[] = []
  private _selected: number = 0
  private _navLast: number = 0
  private _stopListening: (() => void) | null = null

  async onStart() {
    this.visible = false
    this.isOpen = false
    const resume = this._find('Continue') as UIButtonNode
    const fresh = this._find('New Game') as UIButtonNode
    this._buttons = [resume, fresh].filter(b => !!b)
    if (resume) resume.onPress = () => this._continue()
    if (fresh) fresh.onPress = () => this._newGame()
    this._stopListening = this.scene?.addLateUpdate(() => this._listen()) ?? null

    // Loaded (Continue, Load last rest, the editor's Play from save), already let through, or nowhere to save.
    if (!SaveGame.available || SaveGame.loadedFrom || SaveGame.has('started')) return
    let saved = false
    try { saved = await SaveGame.exists(this.slot) } catch { saved = false }
    if (!saved) { SaveGame.set('started', true); return }
    this.open()
  }

  onDespawn() {
    this._stopListening?.()
    this._stopListening = null
    if (this.isOpen) this.close()
  }

  public open(): void {
    this.isOpen = true
    this.visible = true
    this._selected = 0
    this._refresh()
    Game.pause()
    Input.disableMap('Gameplay')
    Input.releaseMouse()
  }

  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Game.resume()
    Input.enableMap('Gameplay')
  }

  private _listen(): void {
    if (!this.isOpen) return
    const nav = Input.vector('Navigate')
    const dy = Math.abs(nav[1]) > 0.5 ? Math.sign(nav[1]) : 0
    // Navigate Y is positive UP; the buttons run top to bottom. One step per press.
    if (dy && dy !== this._navLast && this._buttons.length) {
      this._selected = (this._selected - dy + this._buttons.length) % this._buttons.length
      this._refresh()
    }
    this._navLast = dy
    if (Input.started('Submit')) this._buttons[this._selected]?.onPress()
  }

  /** The selected button lit, the other dim. */
  private _refresh(): void {
    this._buttons.forEach((b, i) => {
      b.tint = i === this._selected ? [0.32, 0.26, 0.16, 1] : [0.18, 0.15, 0.12, 1]
    })
  }

  private _continue(): void {
    this.close()
    SaveGame.load(this.slot, { loadingScreen: { title: 'Hollow Keep' } })
      .catch(e => Logger.warn(`Hollow Keep: Continue could not load the save: ${e?.message ?? e}`, 'Script'))
  }

  private _newGame(): void {
    // The bonfire save stays in its slot until the next bonfire saves over it.
    SaveGame.newGame()
    SaveGame.set('started', true)
    this.close()
  }

  private _find(name: string, under: Node = this): Node {
    for (const child of under.children) {
      if (child.name === name) return child
      const deeper = this._find(name, child)
      if (deeper) return deeper
    }
    return null
  }
}
